// Akte-workflow: leest de multipart-upload en bouwt per document een
// Docling-item (base64). De HELE upload (alle PDF- en Word-bestanden) wordt verwerkt.
// Classificatie: precies één primaire bank-passeeropdracht, één of meer kadaster-stukken,
// overige bestanden = dossier (context bij extractie en placeholder-mapping).

const webhookItem = $input.first();
const b = (webhookItem && webhookItem.binary) || {};
const keys = Object.keys(b);

// Deze workflow kent maar één flow; 'mode' blijft in de items staan omdat
// downstream-nodes (Extract Markdown, specialist-prompts) het veld doorgeven.
const mode = 'akte';

if (keys.length === 0) {
  throw new Error(
    'Webhook ontving geen binary bestanden. Stuur PDF- of Word-bestanden (.docx) als multipart/form-data mee.'
  );
}

function isConvertibleDoc(k) {
  const fn = String(b[k]?.fileName || '').toLowerCase();
  const mime = String(b[k]?.mimeType || '').toLowerCase();
  if (fn.endsWith('.pdf') || mime.includes('pdf')) return true;
  if (fn.endsWith('.docx')) return true;
  if (mime.includes('wordprocessingml') || mime.includes('officedocument.wordprocessingml')) return true;
  return false;
}

const docKeys = keys.filter(isConvertibleDoc);
if (docKeys.length === 0) {
  throw new Error(
    'Geen ondersteunde documenten (PDF of .docx) in de upload.'
  );
}

async function loadAsBase64(binaryKey) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
  return buffer.toString('base64');
}

const base = {
  receivedAt: new Date().toISOString(),
  mode,
};

const BANK_RX_LEGACY = /passeer|nti|rabobank|abnamro|abn[\s_-]?amro|ing|obvion|munt|bank|stater/;
const KAD_RX_LEGACY = /eigendom|kadaster/;

function bankScore(fname) {
  const f = String(fname || '').toLowerCase();
  if (
    /passeerbevestig|passeergegevens|gelden\s+notaris|conceptnota|factuur|\bwwft\b|bankpas|definitieve\s+set|uitbetaling|\bbvi\b|bewijs\s+van\s+inschrijving|aflosnota|rente-?aanbod|royement/i.test(f)
  ) {
    return -100;
  }
  let s = 0;
  if (/passeeropdracht/i.test(f)) s += 200;
  if (/notarisinstructie|voorlopige\s+gegevens/i.test(f)) s += 180;
  if (/rabobank|co[oö]peratieve\s+rabo|abn|abnamro|\bing\b|obvion|regiobank|florius|aegon|asr/i.test(f)) s += 85;
  // Een notarisinstructie (Stater: 'NTI-<nummer>') ís de opdracht en weegt net
  // zo zwaar als een passeeropdracht. Stond dit op 85, dan eindigde hij gelijk
  // met elk stuk dat toevallig een banknaam in de titel heeft — en won het
  // eerste bestand, bijvoorbeeld een bewijs van inschrijving.
  if (/notarisinstructie|\bnti\b/i.test(f)) s += 200;
  if (/nutsworth|stater/i.test(f)) s += 85;
  if (/\bpasseer\b/i.test(f) && !/bevestig|melding|gegevens/i.test(f)) s += 35;
  if (/voorlopig/i.test(f)) s -= 40;
  return s;
}

function isKadasterName(fname) {
  const f = String(fname || '').toLowerCase();
  if (/passeeropdracht|notarisinstructie/i.test(f)) return false;
  if (/passeerbevestig|\bwwft\b|\bfactuur\b|bankpas|uitbetaling|\.eml|conceptnota|nota\s+-/i.test(f)) {
    return false;
  }
  // 'hypotheekinformatie' ontbrak hier: die uitdraai bevat de bestaande
  // inschrijvingen (voorbelasting) en belandde daardoor in de dossier-bak,
  // waarna de akte het onderpand ten onrechte als onbezwaard beschreef.
  return /kadastraal|hypothecair|hypotheekinformatie|eigendomsinformatie|eigendom|kadaster|objectlijst|rechthebbende|brondocument|uittreksel|kadastrale\s+kaart|hypotheekakte|\bkik\b|\bhyp\d|onroerende\s+zaken|perceel/i.test(f);
}

const scored = docKeys.map((k) => {
  const fname = String(b[k]?.fileName || k);
  return { key: k, fname, score: bankScore(fname), kad: isKadasterName(fname) };
});

let primary = null;
let best = -Infinity;
for (const row of scored) {
  if (row.score > best) {
    best = row.score;
    primary = row;
  }
}

const EXPLICIT_BANK = new Set(['passeeropdracht', 'bank', 'file_bank', 'passeeropdracht_0']);
for (const row of scored) {
  const lk = String(row.key || '').toLowerCase();
  if (EXPLICIT_BANK.has(lk)) {
    primary = row;
    best = 9999;
    break;
  }
}

if (!primary || best < 30) {
  const legacyBankKey = docKeys.find((k) =>
    BANK_RX_LEGACY.test(String(b[k]?.fileName || '').toLowerCase())
  );
  if (legacyBankKey) {
    primary = scored.find((s) => s.key === legacyBankKey) || {
      key: legacyBankKey,
      fname: String(b[legacyBankKey]?.fileName || ''),
      score: 50,
      kad: false,
    };
    best = primary.score;
  }
}

if (!primary || best < 30) {
  throw new Error(
    `Geen bank-passeeropdracht herkend in de upload (${docKeys.length} bestand(en)). ` +
      `Voeg de bank-passeeropdracht toe of gebruik een bestandsnaam met «passeeropdracht». ` +
      `Files: ${scored.map((r) => r.fname).join(', ')}`
  );
}

const primaryKey = primary.key;
const kadasterKeys = [];
for (const row of scored) {
  if (row.key === primaryKey) continue;
  if (row.kad || KAD_RX_LEGACY.test(row.fname.toLowerCase())) {
    kadasterKeys.push(row.key);
  }
}

if (kadasterKeys.length === 0) {
  const legacyKad = docKeys.find(
    (k) => k !== primaryKey && KAD_RX_LEGACY.test(String(b[k]?.fileName || '').toLowerCase())
  );
  if (legacyKad) kadasterKeys.push(legacyKad);
}

// Geen afbreking meer als de bestandsnamen niets prijsgeven: dossiers bevatten
// hernoemde downloads en dan zegt de naam niets. Alles gaat door Docling en
// 'Collapse Dossier Markdowns' herkent de kadasterstukken alsnog aan hun
// inhoud. Blijft het daarna leeg, dan pas volgt de foutmelding.
if (kadasterKeys.length === 0) {
  console.warn(
    '[Split Input Files] Geen kadasterstuk aan de bestandsnaam herkend; ' +
      'de inhoudscontrole na Docling moet het overnemen.'
  );
}

const out = [];
for (const row of scored) {
  const k = row.key;
  const blob = await loadAsBase64.call(this, k);
  const fname = b[k]?.fileName || `${k}.pdf`;
  let docType;
  if (k === primaryKey) docType = 'bank';
  else if (kadasterKeys.includes(k)) docType = 'kadaster';
  else docType = 'dossier';
  out.push({
    json: {
      ...base,
      docType,
      filename: fname,
      base64_string: blob,
    },
  });
}

return out;

// Per Docling-response: pak de markdown en bewaar docType + mode + bestandsnaam.
const sourceItem = $('Split Input Files').itemMatching($itemIndex);
const docType = sourceItem?.json?.docType || $json.docType || 'overig';
const mode = sourceItem?.json?.mode || 'akte';
const filename = sourceItem?.json?.filename || '';

const payload = $json;
let md = '';
if (payload?.document?.md_content) md = payload.document.md_content;
else if (payload?.md_content) md = payload.md_content;
else if (payload?.result?.document?.md_content) md = payload.result.document.md_content;
else if (Array.isArray(payload?.documents) && payload.documents[0]?.md_content) md = payload.documents[0].md_content;

if (!md) {
  throw new Error(`Docling gaf geen md_content terug voor ${filename || docType}. Top-level keys: ${Object.keys(payload || {}).join(', ')}`);
}

// Strip ingesloten afbeeldingen. Docling sluit soms volledige bitmaps als
// base64 data-URI in de markdown in (bv. een BRP-uitdraai met logo/foto).
// Die ruis vult de LLM-context (gemeten tot 70%+ van de prompt) en doet het
// model onzin/gibberish produceren. We verwijderen de beelddata; de
// leesbare tekst blijft volledig intact.
function stripEmbeddedImages(text) {
  let t = String(text || '');
  // Markdown-afbeelding met data-URI: ![alt](data:image/png;base64,....)
  t = t.replace(/!\[[^\]]*\]\(\s*data:[^)]*\)/gi, '');
  // HTML <img src="data:...">
  t = t.replace(/<img[^>]*src=["']?data:[^>]*>/gi, '');
  // Vangnet: overgebleven kale data-URI's (contigue base64-reeks).
  t = t.replace(/data:image\/[a-z0-9.+-]+;base64,[A-Za-z0-9+/=]+/gi, '');
  // Opruimen: 3+ opeenvolgende lege regels terugbrengen naar 1 lege regel.
  t = t.replace(/\n{3,}/g, '\n\n');
  return t.trim();
}

md = stripEmbeddedImages(md);

return { json: { docType, mode, filename, markdown: md } };

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'gegevens extraheren', fase: 2 });

// Voegt alle Docling-markdowns samen tot exact twee extractie-items:
// (1) bank — ongewijzigd, (2) kadaster — alle kadaster-documenten achter elkaar.
// Markdown van 'dossier'-bestanden wordt opgeslagen voor de juridische analyse
// (Build Placeholders plakt die achterkadaster_markdown).

const REGISTRY_PATH = '/data/shared/templates/registry.json';
let registry = {};
try { registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8')); } catch (_) {}
const limits = (registry && registry.context_limits) || {};

const items = $input.all();

function clamp(s, max) {
  const t = String(s || '');
  if (t.length <= max) return t;
  return t.slice(0, max) + '\n…[afgekapt voor extractie-context]';
}

const MAX_CHUNK = Number(limits.collapse_per_doc) || 26000;
// Brondocumenten (volledige afschriften van eerdere aktes) zijn veruit de
// grootste stukken, maar leveren maar twee feiten die in hun kop staan: de
// notaris en de passeerdatum. Ongeclampt duwden ze de compacte eigendoms- en
// hypotheekinformatie het contextvenster uit, waarna die velden leeg bleven.
const MAX_BRONDOCUMENT = Number(limits.collapse_brondocument) || 2500;

function kadasterRang(filename) {
  const f = String(filename || '').toLowerCase();
  if (/eigendomsinformatie/.test(f)) return 0;
  if (/hypotheekinformatie|hypothecair/.test(f)) return 1;
  if (/objectlijst/.test(f)) return 2;
  // Akte-PDF's (KIK-concept, minuut, afschrift, cliënt-/bankexemplaar) komen
  // door de bestandsnaamfilter heen en zijn elk zo groot als een heel dossier
  // aan uitdraaien. Ze horen achteraan, net als de brondocumenten.
  if (/brondocument|\bkik\b|hypotheekakte|afschrift|concept|minuut/.test(f)) return 4;
  return 3;
}

// Meest informatiedichte uitdraaien eerst, brondocumenten achteraan: raakt de
// context toch vol, dan sneuvelt het stuk met de minste feiten per teken.
function prioriteerKadaster(kadasterItems) {
  return kadasterItems
    .map((it, i) => ({ it, i }))
    .sort((a, b) =>
      (kadasterRang(a.it.json.filename) - kadasterRang(b.it.json.filename)) || (a.i - b.i))
    .map((r) => r.it);
}
// Elke Kadaster-uitdraai draagt zijn producttitel en een 'BETREFT'-kop in de
// tekst. Daarmee herkennen we een kadasterstuk ook als het bestand hernoemd is
// — de bestandsnaam bepaalt dan niet langer wat er in de akte komt.
function isKadasterUitdraai(md) {
  const t = String(md || '');
  if (/Eigendomsinformatie|Hypotheekinformatie|Kadastraal bericht|Hypothecair bericht/i.test(t)) return true;
  // Een brondocument (afschrift van een eerdere akte) heeft geen BETREFT-kop,
  // maar wel het inschrijvingsstempel van het kadaster. Daaruit haalt de akte
  // de notaris en de passeerdatum van de vorige akte.
  if (/Onroerende\s+Zaken\s+Hyp\s*\d/i.test(t)) return true;
  return /BETREFT/.test(t) && /UW\s+REFERENTIE/i.test(t) && /Kadastrale\s+aanduiding/i.test(t);
}

const bankItems = items.filter((i) => i.json.docType === 'bank');
for (const it of items) {
  if (it.json.docType === 'dossier' && isKadasterUitdraai(it.json.markdown)) {
    it.json.docType = 'kadaster';
  }
}
const kadItems = items.filter((i) => i.json.docType === 'kadaster');
const dossierItems = items.filter((i) => i.json.docType === 'dossier');

if (bankItems.length !== 1) {
  throw new Error(
    `Intern: verwacht 1 bank-document na Docling, kreeg ${bankItems.length}.`
  );
}
if (kadItems.length === 0) {
  throw new Error(
    'Geen kadastrale documenten gevonden: niet aan de bestandsnaam en niet aan de ' +
      'inhoud. Voeg minstens één eigendoms- of hypotheekinformatie toe.'
  );
}

const bankJson = bankItems[0].json;
// Deze blob gaat alleen naar de deterministische parsers; het taalmodel krijgt
// hieronder een eigen, veel kleinere selectie (kadPromptCombined). Daarom geen
// krappe knip meer op brondocumenten: de notaris staat in hun kop, maar het
// inschrijvingsstempel dat het document aan het juiste stuk koppelt staat de
// ene keer bovenin en de andere keer onderaan. Knippen kostte die koppeling en
// dwong een terugval op de bestandsnaam.
const kadCombined = prioriteerKadaster(kadItems)
  .map((it, idx) => {
    const fn = it.json.filename || `kadaster_${idx + 1}.pdf`;
    return `=== KADASTERBRON ${idx + 1}: ${fn} ===\n${clamp(it.json.markdown || '', MAX_CHUNK)}`;
  })
  .join('\n\n');

// De LLM krijgt een ándere, veel kleinere selectie dan de deterministische
// parsers. Die laatste hebben álles nodig (ook de brondocumenten, voor notaris
// en passeerdatum); het model raakt daar juist door van de wijs — het kreeg
// drie volledige akteteksten voorgeschoteld en beschreef vervolgens de akte in
// plaats van de gevraagde kadastrale velden te extraheren. Voor de prompt dus:
// per producttype alleen de nieuwste uitdraai, geen brondocumenten.
function geleverdOp(text) {
  const m = String(text || '').match(
    /GELEVERD\s+OP\s*\|?\s*(\d{2})-(\d{2})-(\d{4})\s*-?\s*(\d{2}):(\d{2})/i
  );
  return m ? Number(m[3] + m[2] + m[1] + m[4] + m[5]) : 0;
}

function productSoort(filename, text) {
  const f = String(filename || '').toLowerCase();
  const t = String(text || '');
  if (/eigendomsinformatie/i.test(f) || /Eigendomsinformatie/.test(t)) return 'eigendom';
  if (/hypotheekinformatie|hypothecair/i.test(f) || /Hypotheekinformatie/.test(t)) return 'hypotheek';
  if (/objectlijst/i.test(f)) return 'objectlijst';
  return kadasterRang(f) === 4 ? 'brondocument' : 'overig';
}

function selecteerVoorPrompt(kadasterItems) {
  const nieuwste = new Map();
  for (const it of kadasterItems) {
    const soort = productSoort(it.json.filename, it.json.markdown);
    if (soort === 'brondocument') continue;
    const huidig = nieuwste.get(soort);
    if (!huidig || geleverdOp(it.json.markdown) > geleverdOp(huidig.json.markdown)) {
      nieuwste.set(soort, it);
    }
  }
  return prioriteerKadaster([...nieuwste.values()]);
}

const MAX_PROMPT_TOTAAL = Number(limits.collapse_prompt_totaal) || 12000;
let promptGebruikt = 0;
const kadPromptCombined = selecteerVoorPrompt(kadItems)
  .map((it, idx) => {
    const ruimte = MAX_PROMPT_TOTAAL - promptGebruikt;
    if (ruimte <= 0) return '';
    const stuk = clamp(it.json.markdown || '', ruimte);
    promptGebruikt += stuk.length;
    return `=== KADASTERBRON ${idx + 1}: ${it.json.filename} ===\n${stuk}`;
  })
  .filter(Boolean)
  .join('\n\n');

// BRP-inzages zijn aan hun bestandsnaam niet te herkennen — dossiers noemen de
// BRP-, CCBR-, CIR- en VIS-uitdraai identiek (naam + tijdstip) — maar wél aan
// hun inhoud. Ze leveren de geboorteplaats, de voornamen voluit en de
// nationaliteit; zonder deze tak bleven de brp.*-paden in registry.json dood.
// Let op: alleen op 'Basisregistratie Personen' filteren is te ruim — die zin
// staat ook onder elke kadastrale uitdraai en in taxatierapporten. Vandaar de
// kop van de uitdraai zelf, of de combinatie van velden die alleen een
// persoonsbevraging heeft.
function isBrpInzage(md) {
  const t = String(md || '');
  if (/BRP[-\s]?bevraging/i.test(t)) return true;
  return /\bBSN\b/.test(t) && /Geslachtsnaam/.test(t) && /Geboorteplaats/.test(t);
}
const brpCombined = dossierItems
  .filter((it) => isBrpInzage(it.json.markdown))
  .map((it, idx) => `=== BRP-INZAGE ${idx + 1}: ${it.json.filename || ''} ===\n${clamp(it.json.markdown || '', MAX_CHUNK)}`)
  .join('\n\n');

const dossierCombined = dossierItems
  .map((it, idx) => {
    const fn = it.json.filename || `dossier_${idx + 1}.pdf`;
    return `=== OVERIG DOSSIERSTUK ${idx + 1}: ${fn} ===\n${clamp(it.json.markdown || '', MAX_CHUNK)}`;
  })
  .join('\n\n');

// dossier_markdown lift mee in beide items i.p.v. workflow-static-state.
// Beide krijgen dezelfde waarde; Build Placeholders leest het uit de
// Aggregate-output (één bron is genoeg, maar dubbel passeren maakt het
// robuust tegen toekomstige refactors).
const rowBase = {
  receivedAt: bankJson.receivedAt,
  mode: bankJson.mode,
  dossier_markdown: dossierCombined,
  brp_markdown: brpCombined,
};

return [
  {
    json: {
      ...rowBase,
      docType: 'bank',
      filename: bankJson.filename,
      markdown: bankJson.markdown,
    },
  },
  {
    json: {
      ...rowBase,
      docType: 'kadaster',
      filename: kadItems.map((i) => i.json.filename).join(' + '),
      markdown: kadCombined,
      markdown_prompt: kadPromptCombined,
    },
  },
];

// Bepaalt voor de bank-doc welke bank het is op basis van keywords in de
// registry, en bouwt vervolgens de juiste extractie-prompt voor de LLM.
// Voor de kadaster-doc gebruikt het de generieke kadaster-prompt.
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const banks = registry.banks || {};
const kadasterPrompt = registry.kadaster_extraction_prompt || '';

const docType = $json.docType;
const markdown = String($json.markdown || '');
// De prompt gebruikt de ingekorte selectie; 'markdown' blijft volledig en gaat
// ongewijzigd door naar Build Placeholders voor de deterministische parsers.
const markdown_prompt = String($json.markdown_prompt || $json.markdown || '');

function renderPrompt(template, md) {
  return String(template || '').split('{{markdown}}').join(md);
}

const dossier_markdown = String($json.dossier_markdown || '');
const brp_markdown = String($json.brp_markdown || '');

if (docType === 'kadaster') {
  if (!kadasterPrompt) {
    throw new Error('registry.json mist kadaster_extraction_prompt.');
  }
  return {
    json: {
      docType,
      bankId: null,
      markdown,
      dossier_markdown,
      brp_markdown,
      chatInput: renderPrompt(kadasterPrompt, markdown_prompt)
    }
  };
}

const lower = markdown.toLowerCase();
let detectedBankId = null;
let bestScore = 0;

for (const [bankId, bank] of Object.entries(banks)) {
  const keywords = bank.keywords || [];
  let score = 0;
  for (const kw of keywords) {
    if (lower.includes(String(kw).toLowerCase())) score++;
  }
  if (score > bestScore) {
    bestScore = score;
    detectedBankId = bankId;
  }
}

if (!detectedBankId) {
  const knownBanks = Object.keys(banks).join(', ') || '(geen)';
  throw new Error(
    `Geen bank kunnen herkennen uit de passeeropdracht. ` +
    `Bekende banken in registry: ${knownBanks}. ` +
    `Vraag een ontwikkelaar om deze bank toe te voegen aan registry.json.`
  );
}

const bankConfig = banks[detectedBankId];
if (!bankConfig.extraction_prompt) {
  throw new Error(`Bank '${detectedBankId}' heeft geen extraction_prompt in registry.`);
}

return {
  json: {
    docType,
    bankId: detectedBankId,
    markdown,
    dossier_markdown,
    brp_markdown,
    chatInput: renderPrompt(bankConfig.extraction_prompt, markdown)
  }
};

// Parseert de LLM-output per document (bank óf kadaster) tot een platte
// structuur. Geen workflow-static-state meer: de daadwerkelijke combinatie
// van bank+kadaster gebeurt in de Aggregate-node 'Combine Bank+Kadaster'
// hierna. Daardoor blokkeert een failure in één tak niet meer een latere
// run (geen lekkende globale accumulator).
const promptItem = $('Build Extraction Prompt').itemMatching($itemIndex);
const docType = promptItem?.json?.docType;
const bankId = promptItem?.json?.bankId;
const markdown = String(promptItem?.json?.markdown || '');
const dossier_markdown = String(promptItem?.json?.dossier_markdown || '');
const brp_markdown = String(promptItem?.json?.brp_markdown || '');

function extractText(j) {
  if (!j || typeof j !== 'object') return '';
  if (typeof j.text === 'string' && j.text) return j.text;
  if (typeof j.output === 'string' && j.output) return j.output;
  if (typeof j.answer === 'string' && j.answer) return j.answer;
  if (typeof j.response === 'string' && j.response) return j.response;
  const gen = j?.response?.generations;
  if (Array.isArray(gen) && gen.length) {
    const first = gen[0];
    if (Array.isArray(first) && first.length) {
      const t = first[0]?.text;
      if (typeof t === 'string' && t) return t;
      const c = first[0]?.message?.content;
      if (typeof c === 'string' && c) return c;
    } else if (first && typeof first === 'object') {
      if (typeof first.text === 'string' && first.text) return first.text;
    }
  }
  if (typeof j?.message?.content === 'string' && j.message.content) return j.message.content;
  if (Array.isArray(j?.message?.content)) {
    const chunks = [];
    for (const p of j.message.content) {
      if (typeof p === 'string') chunks.push(p);
      else if (p && typeof p.text === 'string') chunks.push(p.text);
    }
    if (chunks.length) return chunks.join('');
  }
  return '';
}

function unwrapJsonLike(s) {
  let t = String(s || '').trim();
  const fence = /^```(?:json)?\s*\r?\n?([\s\S]*?)\r?\n?```$/im;
  const m = t.match(fence);
  if (m) return m[1].trim();
  if (t.startsWith('```')) {
    t = t.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '');
  }
  if (t.startsWith('"""')) {
    t = t.replace(/^"""\s*(?:json)?\s*/i, '').replace(/\s*"""\s*$/i, '');
  }
  return t.trim();
}

function extractFirstJsonObject(s) {
  const str = String(s);
  const start = str.indexOf('{');
  if (start < 0) return null;
  let depth = 0;
  let inStr = false;
  let esc = false;
  for (let i = start; i < str.length; i++) {
    const c = str[i];
    if (inStr) {
      if (esc) { esc = false; continue; }
      if (c === '\\') { esc = true; continue; }
      if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') { inStr = true; continue; }
    if (c === '{') depth++;
    else if (c === '}') {
      depth--;
      if (depth === 0) return str.slice(start, i + 1);
    }
  }
  return null;
}

function tryParseJson(raw) {
  const u = unwrapJsonLike(raw);
  try { return JSON.parse(u); } catch (_) {
    const cand = extractFirstJsonObject(u) || extractFirstJsonObject(raw);
    if (cand) { try { return JSON.parse(cand); } catch (_) {} }
  }
  return null;
}

let parsed = null;
const raw = extractText($json).trim();

if (raw) {
  parsed = tryParseJson(raw);
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new Error(
      `LLM output geen parsebare JSON voor ${docType}: ${raw.slice(0, 500)}`
    );
  }
} else {
  const META = new Set(['pairedItem', 'sourceData', '$node']);
  const obj = {};
  for (const k of Object.keys($json || {})) {
    if (!META.has(k) && !k.startsWith('_')) obj[k] = $json[k];
  }
  if (Object.keys(obj).length === 0) {
    throw new Error(
      `Lege LLM output voor ${docType}. Top-level keys: ${Object.keys($json || {}).join(', ')}`
    );
  }
  parsed = obj;
}

const WRAPPER_KEYS = new Set(['document', 'documents', 'data', 'response', 'result', 'output', 'json', 'extraction', 'fields']);
let unwrapDepth = 0;
while (
  parsed && typeof parsed === 'object' && !Array.isArray(parsed) &&
  Object.keys(parsed).length === 1 &&
  WRAPPER_KEYS.has(Object.keys(parsed)[0]) &&
  unwrapDepth < 3
) {
  const inner = parsed[Object.keys(parsed)[0]];
  if (inner && typeof inner === 'object' && !Array.isArray(inner)) {
    parsed = inner;
    unwrapDepth++;
  } else {
    break;
  }
}

return {
  json: {
    docType,
    bankId: bankId || null,
    parsed,
    markdown,
    dossier_markdown,
    brp_markdown,
  }
};

// Bouwt placeholder-map declaratief op basis van de bank-specifieke mapping in
// registry.json. Elke placeholder-tag heeft een lijst met paden in de
// geëxtraheerde data; eerste niet-lege match wordt gebruikt. Voor banken met
// een `conditional_blocks`-config worden bovendien <<#FLAG:NAAM>>-keys
// toegevoegd die door vul_template_in.py gebruikt worden om hele blokken in
// of uit het template te schakelen.
//
// Input: één item met `docs` = [{ docType:'bank', parsed, bankId, markdown },
//                                { docType:'kadaster', parsed, markdown }]
// (geproduceerd door 'Combine Bank+Kadaster' Aggregate-node).
const fs = require('fs');
const REGISTRY_PATH = '/data/shared/templates/registry.json';

const j = $json || {};
const docs = Array.isArray(j.docs) ? j.docs : [];
const bankDoc = docs.find((d) => d && d.docType === 'bank');
const kadDoc = docs.find((d) => d && d.docType === 'kadaster');
if (!bankDoc) {
  throw new Error('Geen bank-document gevonden in samengevoegde Aggregate-input.');
}
if (!kadDoc) {
  throw new Error('Geen kadaster-document gevonden in samengevoegde Aggregate-input.');
}

const bank = bankDoc.parsed || {};
const kadaster = kadDoc.parsed || {};
const bankId = bankDoc.bankId;
const bank_markdown = String(bankDoc.markdown || '');
const kadaster_markdown = String(kadDoc.markdown || '');
const brp_markdown = String((bankDoc && bankDoc.brp_markdown) || (kadDoc && kadDoc.brp_markdown) || '');

if (!bankId) {
  throw new Error('Geen bankId beschikbaar — kon de bank niet detecteren in de bank-doc.');
}

let registry;
try {
  registry = JSON.parse(fs.readFileSync(REGISTRY_PATH, 'utf8'));
} catch (err) {
  throw new Error(`Kon templates-registry niet lezen (${REGISTRY_PATH}): ${err.message}`);
}

const bankConfig = (registry.banks || {})[bankId];
if (!bankConfig) {
  throw new Error(`Bank '${bankId}' niet gevonden in registry.json`);
}
if (!bankConfig.template_filename) {
  throw new Error(`Bank '${bankId}' heeft geen template_filename in registry.`);
}

const data = { bank, kadaster };

// --- Deterministische cliëntnamen uit het kadaster ---
// De LLM-extractie mist de namen regelmatig: bij een grote/ruizige kadasterblob
// komt klanten[] leeg terug, waarna de akte terugvalt op initialen uit de
// passeeropdracht ('M A CRUM'). Het kadasterveld
// 'Naam gerechtigde | <aanhef> <volledige naam>' is echter doodregelmatig; die
// parsen we hier direct en gebruiken we met voorrang. Natuurlijke personen
// hebben altijd een aanhef (De heer/Mevrouw); dat filtert rechtspersonen en
// hypotheek-registraties er betrouwbaar uit.
function _normaliseerAanhef(prefix) {
  const p = String(prefix || '').trim().toLowerCase().replace(/\.$/, '');
  if (p === 'de heer' || p === 'heer' || p === 'dhr') return 'de heer';
  if (p === 'mevrouw' || p === 'mevr' || p === 'mw') return 'mevrouw';
  return '';
}
// Leest een kadastercel. Docling levert dezelfde rij in meerdere vormen aan:
// '| Label | Waarde |' en de samengevallen vorm '| Label Waarde |'. Soms breekt
// de waarde over twee cellen; dan volstaat de afgekapte waarde.
function _kadVeld(tekst, label) {
  const m = String(tekst || '').match(new RegExp(label + '\\s*\\|?\\s*([^|\\n]+)'));
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

// De burgerlijke staat in het kadaster geldt uitsluitend 'ten tijde van
// verkrijging'. Dat is geen eigenschap van de persoon maar van die verkrijging:
// in 2021.0588 staat dezelfde man bij het perceel uit 2009 als ongehuwd en bij
// de percelen uit 2016 als gehuwd. We bewaren de kwalificatie daarom apart in
// plaats van haar weg te knippen; voor de comparitie is de BRP leidend.
function _splitsPeildatum(ruw) {
  const s = String(ruw || '');
  return {
    peildatum: /ten tijde van/i.test(s),
    waarde: s.replace(/\(?\s*ten tijde van.*$/i, '').replace(/\s+/g, ' ').trim(),
  };
}

function _parseKadasterKlanten(md) {
  const t = String(md || '');
  const aanhefRe = /^(de heer|mevrouw|mw|dhr|heer|mevr)\.?\s+/i;
  const re = /Naam gerechtigde\s*\|?\s*([^|\n]+)/g;

  // Ankers eerst verzamelen: 'Aandeel' en 'Soort recht' staan vóór de naam,
  // 'Burgerlijke staat' en 'Betrokken persoon' erna, met soms een paginakop
  // ertussen. Het blok loopt tot de volgende gerechtigde.
  const ankers = [];
  let m;
  while ((m = re.exec(t)) !== null) ankers.push({ index: m.index, eind: re.lastIndex, ruw: m[1] });

  const waarnemingen = [];
  for (let i = 0; i < ankers.length; i++) {
    const a = ankers[i];
    let raw = a.ruw.replace(/\(ten tijde[^)]*\)/ig, '');
    raw = raw.replace(/\s+/g, ' ').trim().replace(/^\|+|\|+$/g, '').trim();
    const am = raw.match(aanhefRe);
    if (!am) continue;
    const aanhef = _normaliseerAanhef(am[1]);
    if (!aanhef) continue;
    const naam = raw.slice(am[0].length).trim();
    if (/\d/.test(naam) || naam.split(/\s+/).length < 2 || !/[A-Za-z]/.test(naam)) continue;

    const volgende = ankers[i + 1] ? ankers[i + 1].index : t.length;
    // De volgende gerechtigde is de echte begrenzing; de tekencap is enkel een
    // vangnet. Hij moet ruim zijn: Docling maakt kolommen van ~130 tekens, dus
    // een krap venster kapte de waarde middenin '(ten tijde van verkrijging)' af.
    const na = t.slice(a.eind, Math.min(volgende, a.eind + 3000));
    // De kwalificatie '(ten tijde van verkrijging)' kan door Docling in een
    // aparte cel belanden; lees haar daarom van de hele regel, niet van de cel.
    const bsRegel = (na.match(/^.*Burgerlijke staat.*$/m) || [''])[0];
    const bs = _splitsPeildatum(_kadVeld(na, 'Burgerlijke staat'));
    if (/ten tijde van/i.test(bsRegel)) bs.peildatum = true;
    const betrokken = _splitsPeildatum(_kadVeld(na, 'Betrokken persoon')).waarde
      .replace(/Persoonsgegevens zijn ontleend.*$/i, '').replace(/\s+/g, ' ').trim();

    // Achteruit kijken, maar nooit voorbij de vorige gerechtigde: anders erft
    // deze persoon het aandeel van de vorige.
    const vorige = i > 0 ? ankers[i - 1].eind : 0;
    const voor = t.slice(Math.max(vorige, a.index - 900), a.index);
    const aandeelHits = voor.match(/Aandeel\s*\|?\s*(\d+\s*\/\s*\d+)/gi) || [];
    const laatsteA = aandeelHits.length ? aandeelHits[aandeelHits.length - 1] : '';
    const aandeel = laatsteA
      ? (laatsteA.match(/(\d+)\s*\/\s*(\d+)/) || []).slice(1, 3).join('/') : '';
    const soortHits = voor.match(/Soort recht\s*\|?\s*([^|\n]+)/gi) || [];
    const laatsteS = soortHits.length ? soortHits[soortHits.length - 1] : '';
    const soort_recht = laatsteS
      ? laatsteS.replace(/Soort recht\s*\|?\s*/i, '').replace(/\s+/g, ' ').trim() : '';

    waarnemingen.push({
      aanhef,
      naam_hoofdletters: naam.toUpperCase(),
      volledige_naam: naam,
      burgerlijke_staat: bs.waarde.toLowerCase(),
      burgerlijke_staat_peildatum: bs.peildatum,
      betrokken_persoon: betrokken,
      aandeel,
      soort_recht,
    });
  }

  // Ontdubbelen op naam, maar waarnemingen samenvoegen: dezelfde persoon komt
  // in meerdere uitdraaien voor, soms met een andere burgerlijke staat.
  const perNaam = new Map();
  for (const w of waarnemingen) {
    const k = w.naam_hoofdletters;
    if (!perNaam.has(k)) perNaam.set(k, { ...w, burgerlijke_staat_varianten: [], aandelen: [] });
    const rec = perNaam.get(k);
    if (w.burgerlijke_staat && !rec.burgerlijke_staat_varianten.includes(w.burgerlijke_staat)) {
      rec.burgerlijke_staat_varianten.push(w.burgerlijke_staat);
    }
    if (w.aandeel && !rec.aandelen.includes(w.aandeel)) rec.aandelen.push(w.aandeel);
    // Eerste niet-lege waarneming wint, zodat bestaand gedrag niet verschuift.
    for (const veld of ['burgerlijke_staat', 'betrokken_persoon', 'aandeel', 'soort_recht']) {
      if (!rec[veld] && w[veld]) rec[veld] = w[veld];
    }
    if (w.burgerlijke_staat_peildatum) rec.burgerlijke_staat_peildatum = true;
  }
  return Array.from(perNaam.values());
}
const _detKlanten = _parseKadasterKlanten(kadaster_markdown);
if (_detKlanten.length) {
  const _existing = Array.isArray(data.kadaster.klanten) ? data.kadaster.klanten : [];
  // Merge: behoud reeds geëxtraheerde velden (geboorteplaats/-datum/voornamen)
  // en overschrijf uitsluitend naam + aanhef met de betrouwbare kadaster-waarde.
  data.kadaster.klanten = _detKlanten.map((dk, i) => ({
    ...(_existing[i] || {}),
    aanhef: dk.aanhef,
    naam_hoofdletters: dk.naam_hoofdletters,
    volledige_naam: dk.volledige_naam,
    burgerlijke_staat: dk.burgerlijke_staat,
    burgerlijke_staat_peildatum: dk.burgerlijke_staat_peildatum,
    burgerlijke_staat_varianten: dk.burgerlijke_staat_varianten,
    betrokken_persoon: dk.betrokken_persoon,
    aandeel: dk.aandeel,
    aandelen: dk.aandelen,
    soort_recht: dk.soort_recht,
    // Wie in het kadaster staat is rechthebbende; comparanten die alleen uit
    // de bankopdracht komen (medeschuldenaar, echtgenoot) krijgen false. Het
    // verschil bepaalt of een ontbrekende naam kritiek is of normaal.
    is_rechthebbende: true,
  }));
}

// --- Deterministische persoonsgegevens uit de BRP-inzage ---
// De BRP-uitdraai heeft vaste labels ('Voornamen', 'Geslachtsnaam',
// 'Geboorteplaats'); die parsen we rechtstreeks in plaats van er een
// LLM-ronde aan te wijden. Hiermee worden de brp.*-paden in registry.json,
// die tot nu toe altijd op undefined uitkwamen, eindelijk gevuld.
// Een BRP-label mag alleen als hele cel of hele regel gelden. De losse
// deelstring-match die hier eerder stond, las 'Geslachtsnaam' als het veld
// 'Geslacht' (en leverde 'snaam' op, waardoor de aanhef altijd leeg bleef),
// pakte de kop '## Nationaliteit' als waarde van 'Nationaliteit', en gaf een
// persoon zonder eigen voorvoegsel het woord uit 'Voorvoegsel partner' als
// tussenvoegsel — 'Maria Wilhelmina partner Rochat' in de akte.
// _brpRegelVeld doet dit al goed; er is geen tweede lezer nodig.

// Een lege cel laat de volgende labelregel als 'waarde' achter: Docling
// rendert sommige tabellen kolomsgewijs, eerst alle labels en dan pas de
// waarden ('Datum Plaats Land' gevolgd door de drie waarden). Een waarde die
// zelf een BRP-label is, is dus geen waarde.
const _BRP_LABEL_RX = new RegExp('^(?:A-nummer|BSN|Voornamen|Voorvoegsels?|Geslachtsnaam|' +
  'Geboortedatum|Geboorteplaats|Geboorteland|Geslacht|Naam gebruik|Gemeente|Nationaliteit|' +
  'Datum|Plaats|Land|Soort verbintenis|Datum ontbinding|Plaats ontbinding|Land ontbinding|' +
  'Reden ontbinding|Beschrijving document|Ingangsdatum geldigheid|Datum opneming GBA|' +
  'Aktenummer|Register gemeente akte)(?: partner)?$', 'i');

// De BRP-uitdraai zet label en waarde op afzonderlijke regels. Een los 'Datum'
// zou daarom 'Datum opneming GBA' vangen; we ankeren op een regel die niets
// anders bevat dan het label, en vallen terug op de tabelvorm.
// Kolomvorm: Docling zet bij sommige uitdraaien eerst alle labels van een
// tabel en dan pas alle waarden ('Nationaliteit / Ingangsdatum geldigheid /
// Nederlandse / 00-00-0000'). Label en waarde staan dan zo ver uit elkaar als
// het labelblok breed is; we koppelen ze op positie binnen dat blok. Werkt ook
// op de gewone afwisselende vorm, waar het blok één label breed is.
function _brpKolomVeld(tekst, label) {
  const regels = String(tekst || '')
    .split(/\r?\n/)
    .map((r) => r.replace(/\|/g, ' ').trim())
    .filter((r) => r && !/^!\[Image\]/.test(r));
  const isLabel = (r) => _BRP_LABEL_RX.test(r);
  const rx = new RegExp('^' + label + '$');
  const i = regels.findIndex((r) => rx.test(r));
  if (i < 0 || !isLabel(regels[i])) return '';
  let a = i;
  let b = i;
  while (a > 0 && isLabel(regels[a - 1])) a--;
  while (b + 1 < regels.length && isLabel(regels[b + 1])) b++;
  const waarde = regels[b + 1 + (i - a)];
  return waarde && !isLabel(waarde) ? waarde : '';
}

function _brpRegelVeld(sectie, label) {
  const t = String(sectie || '');
  const schoon = (waarde, striptPijp) => {
    let v = String(waarde || '');
    if (striptPijp) v = v.replace(/\|/g, ' ');
    v = v.replace(/\s+/g, ' ').trim();
    return _BRP_LABEL_RX.test(v) ? '' : v;
  };
  const m1 = t.match(new RegExp('^[ \\t|]*' + label + '[ \\t|]*$\\r?\\n+[ \\t|]*([^\\n]+)', 'm'));
  if (m1) {
    const v = schoon(m1[1], true);
    if (v) return v;
  }
  const m2 = t.match(new RegExp('^[ \\t]*\\|?[ \\t]*' + label + '[ \\t]*\\|[ \\t]*([^|\\n]+)', 'm'));
  if (m2) {
    const v = schoon(m2[1], false);
    if (v) return v;
  }
  // Beide directe vormen leverden niets of alleen een volgend label op: dan is
  // dit een kolomsgewijs gerenderde tabel.
  return _brpKolomVeld(t, label);
}

// 'Datum' komt zowel onder 'Huwelijk/partnerschap' als onder
// 'Huwelijks geschiedenis 1' voor; zonder afbakening pakken we de verkeerde.
// Alle '##'-subsecties waarvan de kop op het patroon past, in documentvolgorde.
// Nodig voor de geschiedenis-secties: die zijn genummerd ('Huwelijks
// geschiedenis 1', '... 2'), dus een vaste kop volstaat daar niet.
function _brpSubsecties(sectie, rx) {
  const t = String(sectie || '');
  const koppen = [];
  const re = /^##[ \t]*(.+?)[ \t]*$/gm;
  let m;
  while ((m = re.exec(t)) !== null) koppen.push({ kop: m[1], index: m.index, start: re.lastIndex });
  return koppen
    .map((k, i) => ({
      kop: k.kop,
      tekst: t.slice(k.start, i + 1 < koppen.length ? koppen[i + 1].index : t.length),
    }))
    .filter((s) => rx.test(s.kop));
}

function _brpSubsectie(sectie, kop) {
  const t = String(sectie || '');
  const m = t.match(new RegExp('^##\\s*' + kop + '\\s*$', 'm'));
  if (!m) return '';
  const rest = t.slice(m.index + m[0].length);
  const eind = rest.search(/^##\s+/m);
  return eind < 0 ? rest : rest.slice(0, eind);
}

function _parseBrpPersonen(md) {
  const t = String(md || '');
  const secties = t.split(/^=== BRP-INZAGE \d+: .*? ===$/m).filter((s) => s.trim());
  const personen = [];
  const gezien = new Set();
  for (const sectie of (secties.length ? secties : [t])) {
    // Persoonsgegevens uitsluitend uit de eigen '## Persoon'-sectie lezen. De
    // uitdraai herhaalt dezelfde labels verderop voor de partner ('Voorvoegsel
    // partner') en voor elk kind ('## Kind'); zonder die afbakening erft een
    // persoon zonder eigen voorvoegsel het woord 'partner' als tussenvoegsel.
    const _persoon = _brpSubsectie(sectie, 'Persoon') || sectie;
    // Hoofdletter-gevoelig: 'Naam gebruik eigen geslachtsnaam' verderop in de
    // uitdraai mag het veld 'Geslachtsnaam' niet overschaduwen.
    const geslachtsnaam = _brpRegelVeld(_persoon, 'Geslachtsnaam');
    const voornamen = _brpRegelVeld(_persoon, 'Voornamen');
    // De BRP houdt het tussenvoegsel apart ('Voorvoegsel de'); zonder dit veld
    // wordt 'Anna Alida de Klerk' in de akte 'ANNA ALIDA KLERK'. De uitdraai
    // schrijft het label zowel enkelvoud als meervoud.
    const tussenvoegsel = _brpRegelVeld(_persoon, 'Voorvoegsels?');
    if (!geslachtsnaam) continue;
    const volledige_naam = [voornamen, tussenvoegsel, geslachtsnaam].filter(Boolean).join(' ');
    const sleutel = volledige_naam.toUpperCase();
    if (gezien.has(sleutel)) continue;
    gezien.add(sleutel);
    const plaats = _brpRegelVeld(_persoon, 'Geboorteplaats');
    const land = _brpRegelVeld(_persoon, 'Geboorteland');
    const geslacht = _brpRegelVeld(_persoon, 'Geslacht');
    // Huwelijk/partnerschap: de BRP is de enige bron die de HUIDIGE burgerlijke
    // staat geeft. Het kadaster kent alleen de staat ten tijde van verkrijging,
    // en die kan tientallen jaren oud zijn.
    const _hw = _brpSubsectie(sectie, 'Huwelijk/partnerschap');
    const _partnerNaam = [
      _brpRegelVeld(_hw, 'Voornamen partner'),
      _brpRegelVeld(_hw, 'Voorvoegsel partner'),
      _brpRegelVeld(_hw, 'Geslachtsnaam partner'),
    ].filter(Boolean).join(' ').trim();
    // De BRP zet de datum van elke verbintenis in een eigen genummerde
    // 'Huwelijks geschiedenis'-sectie; partner en ontbinding staan alleen bij
    // de laatste, in 'Huwelijk/partnerschap'. Meer dan één datum betekent dus
    // meer dan één huwelijk of partnerschap — de eerdere partner staat niet in
    // de uitdraai en is hier dus niet te kennen.
    //
    // In de geschiedenis-secties lezen we de datum niet op label: Docling
    // rendert die tabel bij sommige uitdraaien kolomsgewijs (eerst 'Datum
    // Plaats Land', dan pas de waarden), waardoor een labelgestuurde lezing
    // 'Plaats' als datum oplevert. Zo'n sectie bevat maar één datum, dus de
    // eerste datumvormige waarde is de juiste — en alles wat niet als datum
    // leest valt af in plaats van als tweede huwelijk te tellen.
    const _verbintenisDatums = [];
    const _voegDatumToe = (waarde) => {
      const m = String(waarde || '').match(/\b(\d{2}-\d{2}-\d{4})\b/);
      if (m && !_verbintenisDatums.includes(m[1])) _verbintenisDatums.push(m[1]);
    };
    _voegDatumToe(_brpRegelVeld(_hw, 'Datum'));
    for (const sub of _brpSubsecties(sectie, /^(huwelijk|partnerschap)\w*\s+geschiedenis/i)) {
      _voegDatumToe(sub.tekst);
    }
    const _redenOntbinding = _brpRegelVeld(_hw, 'Reden ontbinding');
    const _datumOntbinding = _brpRegelVeld(_hw, 'Datum ontbinding');
    const _soortVerbintenis = _brpRegelVeld(_hw, 'Soort verbintenis');
    const huwelijk = _partnerNaam ? {
      partner_naam: _partnerNaam,
      partner_geboortedatum: _brpRegelVeld(_hw, 'Geboortedatum partner'),
      soort_verbintenis: _soortVerbintenis,
      datum: _brpRegelVeld(_hw, 'Datum'),
      plaats: _brpRegelVeld(_hw, 'Plaats'),
      datum_ontbinding: _datumOntbinding,
      reden_ontbinding: _redenOntbinding,
      // Ontbonden door overlijden is GEEN echtscheiding: de persoon is weduwe
      // of weduwnaar en er speelt een nalatenschap, geen ex-partner.
      ontbonden_door_overlijden: /overlijden/i.test(_redenOntbinding),
      actueel: !(_datumOntbinding || _redenOntbinding),
    } : null;
    personen.push({
      huwelijk,
      verbintenis_datums: _verbintenisDatums,
      volledige_naam,
      naam_hoofdletters: sleutel,
      voornamen,
      achternaam: geslachtsnaam,
      tussenvoegsel,
      // Notariële schrijfwijze: bij een geboorte buiten Nederland hoort het
      // land erbij ('geboren te Buzau, Roemenië').
      geboorteplaats: plaats && land && !/nederland/i.test(land)
        ? plaats + ', ' + land
        : plaats,
      geboorteland: land,
      geboortedatum: _brpRegelVeld(_persoon, 'Geboortedatum'),
      // Nationaliteit staat niet in '## Persoon' maar in een eigen sectie.
      nationaliteit: _brpRegelVeld(_brpSubsectie(sectie, 'Nationaliteit') || sectie, 'Nationaliteit'),
      aanhef: /^vrouw$/i.test(geslacht) ? 'mevrouw' : (/^man$/i.test(geslacht) ? 'de heer' : ''),
    });
  }
  return personen;
}

// De BRP-inzages staan in willekeurige volgorde in het dossier; koppel ze op
// achternaam aan de rechthebbenden uit het kadaster, zodat klant 1 in de akte
// ook de BRP-gegevens van klant 1 krijgt.
function _achternaamSleutel(naam) {
  const schoon = String(naam || '').normalize('NFKD').replace(/[̀-ͯ]/g, '')
    .replace(/[^A-Za-z ]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!schoon) return '';
  const delen = schoon.split(' ');
  return delen[delen.length - 1];
}

// Een Stater-instructie richt zich in de aanhef aan alle schuldenaren
// ('De heer P.J. Tankens en mevrouw T.H. Floor'). Dat is een betrouwbaardere
// bron dan het genummerde gegevensblok: Docling laat daar de tweede persoon
// soms helemaal wegvallen bij het omzetten van de tabelcel.
function _parseStaterClienten(md) {
  const t = String(md || '').replace(/\s+/g, ' ');
  const regel = t.match(
    /((?:De heer|Mevrouw)\s+[A-Z]\.(?:[A-Z]\.)*\s+[A-Za-zÀ-ÿ'’-]+(?:\s+(?:en|,)\s+(?:de heer|mevrouw)\s+[A-Z]\.(?:[A-Z]\.)*\s+[A-Za-zÀ-ÿ'’-]+)+)/i
  );
  if (!regel) return [];
  const uit = [];
  const re = /(de heer|mevrouw)\s+((?:[A-Z]\.)+)\s+((?:van |de |der |den |ten |ter )?[A-Za-zÀ-ÿ'’-]+)/gi;
  let m;
  while ((m = re.exec(regel[1])) !== null) {
    uit.push({
      aanhef: /mevrouw/i.test(m[1]) ? 'mevrouw' : 'de heer',
      initialen: m[2],
      achternaam: m[3].trim(),
    });
  }
  return uit;
}

// De comparanten van de akte zijn de schuldenaren uit de bankopdracht; het
// kadaster noemt alleen de rechthebbenden. Bij een echtpaar waarvan er één
// eigenaar is, staan er dus twee in de akte en één in het kadaster. De langste
// lijst is de leidraad.
const _kadNamen = Array.isArray(data.kadaster.klanten) ? data.kadaster.klanten : [];
let _bankNamen = Array.isArray(data.bank.klanten) ? data.bank.klanten : [];
if (_bankNamen.length <= _kadNamen.length) {
  // Terugval op de aanhef van de instructie; die noemt alle schuldenaren.
  const _uitAanhef = _parseStaterClienten(bank_markdown);
  if (_uitAanhef.length > _bankNamen.length) {
    _bankNamen = _uitAanhef.map((c) => ({
      volledige_naam: `${c.initialen} ${c.achternaam}`,
      aanhef: c.aanhef,
    }));
  }
}
if (_bankNamen.length > _kadNamen.length) {
  const _bestaand = new Set(_kadNamen.map((k) => _achternaamSleutel(k.volledige_naam)));
  for (const b of _bankNamen) {
    const naam = b.volledige_naam || b.naam_hoofdletters || '';
    const sleutel = _achternaamSleutel(naam);
    if (!naam || _bestaand.has(sleutel)) continue;
    _bestaand.add(sleutel);
    _kadNamen.push({
      volledige_naam: naam,
      naam_hoofdletters: naam.toUpperCase(),
      aanhef: b.aanhef || '',
      is_rechthebbende: false,
    });
  }
  data.kadaster.klanten = _kadNamen;
}

const _brpPersonen = _parseBrpPersonen(brp_markdown);
if (_brpPersonen.length) {
  const _kadKlanten = Array.isArray(data.kadaster.klanten) ? data.kadaster.klanten : [];
  data.brp = {
    klanten: _kadKlanten.length
      ? _kadKlanten.map((k) =>
          _brpPersonen.find(
            (p) => _achternaamSleutel(p.volledige_naam) === _achternaamSleutel(k.volledige_naam)
          ) || {})
      : _brpPersonen,
  };
}

// --- Deterministisch onderpand-adres uit het kadaster ---
// De bank-extractie levert het adres onbetrouwbaar: arrays, lege velden of
// zelfs kadastrale nummers i.p.v. de straat, wat als '[object Object]' in de
// akte belandt. Het kadaster is gestructureerd; die parsen we hier en
// gebruiken we met voorrang boven de bank.
//
// 'Locatie' (BAG) gaat vóór 'Adres': Adres is het woonadres van de
// gerechtigde en staat in kapitalen, Locatie is het onderpandadres in de
// juiste schrijfwijze. Uit die kapitalen viel 'Capelle Aan Den Ijssel' niet
// meer netjes te herstellen.
const _PLAATS_KLEINE_WOORDEN = new Set([
  'aan', 'den', 'der', 'de', 'het', 'op', 'in', 'te', 'van', 'bij', 'ter', 'tot', "'s", 'a/d',
]);

function _nettePlaatsnaam(s) {
  const ruw = String(s || '').replace(/\s+/g, ' ').trim();
  if (!ruw) return '';
  // Staat de bron al in gemengde schrijfwijze, dan is die correct: niet
  // 'verbeteren'. Alleen kapitalen worden teruggezet.
  if (ruw !== ruw.toUpperCase()) return ruw;
  return ruw
    .toLowerCase()
    .split(' ')
    .map((w, i) => {
      if (i > 0 && _PLAATS_KLEINE_WOORDEN.has(w)) return w;
      // Ook na een koppelteken een hoofdletter: Groot-Ammers, 's-Hertogenbosch.
      return w.split('-').map((deel) => {
        // Nederlandse IJ-digraaf krijgt twee hoofdletters: IJssel, IJmuiden.
        if (deel.startsWith('ij')) return 'IJ' + deel.slice(2);
        return deel.charAt(0).toUpperCase() + deel.slice(1);
      }).join('-');
    })
    .join(' ');
}

function _parseKadasterAdresMetLabel(md, label) {
  const t = String(md || '');
  const re = new RegExp(label + '\\s*\\|?\\s*([^|\\n]{3,90})', 'gi');
  let m;
  while ((m = re.exec(t)) !== null) {
    // Straat + huisnummer staan op de labelregel; postcode en woonplaats zetten
    // Docling nogal eens op een eigen tabelrij eronder. Daarom een venster.
    const straatM = m[1].match(/^\s*([A-Za-zÀ-ÿ.'’\- ]+?)\s+(\d+[a-zA-Z]?(?:[-\/]\d+[a-zA-Z]?)?)\s*[a-zA-Z]?\s*$/);
    if (!straatM) continue;
    const venster = t.slice(m.index, m.index + 400);
    const pcM = venster.match(/(\d{4})\s*([A-Za-z]{2})\s+([A-Za-zÀ-ÿ.'’\- ]{2,40}?)\s*(?:\||\n|$)/);
    if (!pcM) continue;
    // Toevoeging achter het huisnummer ('1 a') meenemen.
    const toevoeging = (m[1].match(/\d+[a-zA-Z]?(?:[-\/]\d+[a-zA-Z]?)?\s+([a-zA-Z])\s*$/) || [])[1] || '';
    return {
      onderpand_straat: _nettePlaatsnaam(straatM[1]),
      onderpand_huisnummer: straatM[2].trim() + (toevoeging ? ' ' + toevoeging.toUpperCase() : ''),
      onderpand_postcode: pcM[1] + ' ' + pcM[2].toUpperCase(),
      onderpand_woonplaats: _nettePlaatsnaam(pcM[3]),
    };
  }
  return null;
}

// Uitsluitend op 'Locatie' (het BAG-adres van het object). Het veld 'Adres'
// hoort bij een persoon of rechtspersoon in de uitdraai — bij een
// hypotheekhouder is dat het adres van de bank, en dat is als onderpandadres
// natuurlijk onbruikbaar.
function _parseKadasterAdres(md) {
  return _parseKadasterAdresMetLabel(md, 'Locatie');
}

// Kopgegevens van de akte: het offertenummer is het dossierkenmerk van de
// bank (staat in de passeeropdracht ónder 'Afzender:'; het kenmerk onder
// 'Ontvanger:' is dat van het notariskantoor en vaak 'onbekend'). Het eigen
// dossiernummer staat als 'UW REFERENTIE' op de kadastrale uitdraaien.
function _parseOffertenummer(md) {
  const t = String(md || '');
  // ABN AMRO/Stater-notarisinstructie noemt het nummer met zoveel woorden; de
  // variant met '.000' erachter is een subnummer van dezelfde offerte.
  // a.s.r.-nummers beginnen met één cijfer ('1.918.244'), ABN met drie.
  let expliciet = t.match(/offertenummer\s*:?\s*(\d+(?:\.\d+)+|\d{6,})/i);
  if (expliciet) return expliciet[1].replace(/\.000$/, '');
  expliciet = t.match(/Referentienummer[\s\S]{0,80}?\b(\d{3}\.\d{3}\.\d{3})\b/i);
  if (expliciet) return expliciet[1];
  const pos = t.search(/Afzender\s*:/i);
  if (pos < 0) return '';
  const venster = t.slice(pos, pos + 400);
  // Docling plakt de kolomwaarden van het afzenderblok op één regel
  // ('Coöperatieve Rabobank U.A. 4003432160 Service Centrum Wonen ...'), zodat
  // de labels eronder leeg achterblijven. Het dossierkenmerk is het lange
  // cijfernummer in dat blok.
  const nummer = venster.match(/\b(\d{8,14})\b/);
  if (nummer) return nummer[1];
  const m = venster.match(/Dossierkenmerk\s*:\s*\n*\s*([A-Za-z0-9._\/-]+)/i);
  if (m && !/^(onbekend|contactpersoon|telefoonnummer|betreft|afzender)$/i.test(m[1])) return m[1];
  return '';
}

function _parseDossiernummer(md) {
  const m = String(md || '').match(/UW\s+REFERENTIE\s*\|?\s*([A-Za-z0-9][A-Za-z0-9._\/-]*)/i);
  return m ? m[1] : '';
}

const _detAdres = _parseKadasterAdres(kadaster_markdown);
if (_detAdres) Object.assign(data.kadaster, _detAdres);

// ---------------------------------------------------------------------------
// Deterministische kadasterparsers: aanduiding, grootte, voorbelasting,
// verkrijging
// ---------------------------------------------------------------------------
// Alles hieronder komt uit vaste, gelabelde velden in de Kadaster-uitdraaien en
// de brondocumenten. Geen LLM: de blob is groter dan het contextvenster, dus
// wat we hier niet zelf parsen valt regelmatig stil weg. De ruwe feiten gaan
// als JSON naar het Python-vulscript, dat er Nederlandse akte-zinnen van maakt
// (daar zitten de getal-/datum-naar-woorden-helpers al).

// De kadaster-blob is een aaneenschakeling van '=== KADASTERBRON n: <bestand> ==='
// secties; per bron willen we apart kunnen kijken welk soort uitdraai het is.
function _splitKadasterBronnen(md) {
  const t = String(md || '');
  const re = /^=== KADASTERBRON \d+: (.+?) ===$/gm;
  const out = [];
  let m, vorige = null;
  while ((m = re.exec(t)) !== null) {
    if (vorige) out.push({ filename: vorige.filename, text: t.slice(vorige.start, m.index) });
    vorige = { filename: m[1], start: re.lastIndex };
  }
  if (vorige) out.push({ filename: vorige.filename, text: t.slice(vorige.start) });
  if (!out.length) out.push({ filename: '', text: t });
  return out;
}

// 'GELEVERD OP 28-01-2026 - 10:42' -> 202601281042, zodat we de meest recente
// uitdraai kunnen kiezen. Een oudere uitdraai kan een pas ingeschreven
// hypotheek of beslag missen; die kant van de fout is de gevaarlijke.
function _geleverdOp(text) {
  const m = String(text || '').match(
    /GELEVERD\s+OP\s*\|?\s*(\d{2})-(\d{2})-(\d{4})\s*-?\s*(\d{2}):(\d{2})/i
  );
  if (!m) return 0;
  return Number(m[3] + m[2] + m[1] + m[4] + m[5]);
}

function _recentsteBron(bronnen, rx) {
  const kandidaten = bronnen.filter((b) => rx.test(b.filename) || rx.test(b.text));
  if (!kandidaten.length) return null;
  kandidaten.sort((a, b) => _geleverdOp(b.text) - _geleverdOp(a.text));
  return kandidaten[0];
}

// 'Kadastrale aanduiding | Capelle aan den IJssel D 4057'
function _parseKadastraleAanduiding(text) {
  const m = String(text || '').match(
    /Kadastrale\s+aanduiding\s*\|?\s*([A-Za-zÀ-ÿ.'’\- ]+?)\s+([A-Z]{1,2})\s+(\d+)\b/
  );
  if (!m) return null;
  return {
    kadastrale_gemeente: m[1].replace(/\s+/g, ' ').trim(),
    kadastrale_sectie: m[2],
    kadastrale_nummer: m[3],
  };
}

// 'Kadastrale grootte | 116 m²' of '1 ha 20 a 5 ca' -> oppervlakte in m².
// Het Python-vulscript maakt er 'een are en zestien centiare (1 a 16 ca)' van.
function _parseKadastraleGrootte(text) {
  const t = String(text || '');
  const m = t.match(/Kadastrale\s+grootte\s*\|?\s*([\d.]+)\s*(?:m²|m2|m\^2)/i);
  if (m) return String(parseInt(m[1].replace(/\./g, ''), 10));
  const h = t.match(/Kadastrale\s+grootte\s*\|?\s*(?:(\d+)\s*ha\b)?\s*(?:(\d+)\s*a\b)?\s*(?:(\d+)\s*ca\b)?/i);
  if (h && (h[1] || h[2] || h[3])) {
    return String((Number(h[1] || 0) * 10000) + (Number(h[2] || 0) * 100) + Number(h[3] || 0));
  }
  return '';
}

// Namen in een akte worden met initialen aangehaald: 'Judith Jebbigjen
// Besse-Bultsma' -> 'J.J. Besse-Bultsma', 'Leendert van Veen' -> 'L. van Veen'.
// Tussenvoegsels (kleine letter) horen bij de achternaam.
function _naarInitialen(volledig) {
  const woorden = String(volledig || '').replace(/\s+/g, ' ').trim().split(' ').filter(Boolean);
  if (woorden.length < 2) return String(volledig || '').trim();
  let i = woorden.length - 1;
  while (i > 0 && /^[a-z']/.test(woorden[i - 1])) i--;
  const voornamen = woorden.slice(0, i);
  const achternaam = woorden.slice(i).join(' ');
  if (!voornamen.length) return achternaam;
  return voornamen.map((w) => w.charAt(0).toUpperCase() + '.').join('') + ' ' + achternaam;
}

// Wie de akte heeft gepasseerd, staat in een kadastraal brondocument op twee
// plekken: in de comparitie ('verschenen voor mij, mr. X ...') en soms in de
// afschriftverklaring erboven ('Ondergetekende, mr. X ...'). Alleen op die
// tweede afgaan werkt niet: een UITTREKSEL heeft die verklaring niet. De
// comparitie staat er altijd, dus die gaat voor.
const _NAAM = "([A-Za-zÀ-ÿ.'’\\- ]+?)";
// Titels lopen uiteen: 'mr.', 'mr', 'meester', al dan niet met 'mevrouw' of
// 'de heer' ervoor. En een notaris is 'notaris te', 'notaris gevestigd te' of
// 'gedefungeerd notaris te'.
const _TITEL = "(?:mevrouw\\s+|de\\s+heer\\s+)?(?:mr\\.?|meester)\\s*";
const _NOTARIS_TE = ",\\s*(?:gedefungeerd\\s+)?notaris(?:,)?(?:\\s+gevestigd)?\\s+te\\s*";
const _AANHEF = "(?:verschenen voor mij|Ondergetekende)";
const _NOTARIS_PATRONEN = [
  // toegevoegd notaris, passerend in het protocol van een ander
  {
    re: new RegExp(_AANHEF + ',\\s*' + _TITEL + _NAAM +
      ',\\s*toegevoegd notaris[\\s\\S]{0,150}?bevoegd om akten te passeren in het protocol van\\s*' +
      _TITEL + _NAAM + _NOTARIS_TE + _NAAM + '[:,.]', 'i'),
    maak: (m) => 'mr. ' + _naarInitialen(m[1]) + ', toegevoegd notaris, bevoegd om akten te passeren ' +
      'in het protocol van mr. ' + _naarInitialen(m[2]) + ', notaris te ' + m[3].trim(),
  },
  // waarnemer van een vacant protocol: staat het protocol van de gedefungeerde
  // notaris nog open, dan passeert een (zware) waarnemer daarin. De akte noemt
  // dan niet de waarnemer maar het protocol waarin hij passeerde. Dit patroon
  // moet vóór het algemene waarnemer-patroon staan: daar past de naam van de
  // protocolhouder niet in, omdat er tussen hem en 'notaris te' nog een
  // hoedanigheid staat.
  {
    re: new RegExp(_AANHEF + ',\\s*' + _TITEL + _NAAM +
      ',[\\s\\S]{0,250}?(zware\\s+)?waarnemer van het vacante protocol van\\s*' +
      _TITEL + _NAAM + _NOTARIS_TE + _NAAM + '[:,.]', 'i'),
    maak: (m) => 'een ' + (m[2] ? 'zware ' : '') + 'waarnemer van het vacante protocol van mr. ' +
      _naarInitialen(m[3]) +
      (/gedefungeerd\s+notaris/i.test(m[0]) ? ', gedefungeerd notaris te ' : ', notaris te ') +
      m[4].trim(),
  },
  // waarnemer van de notaris
  {
    re: new RegExp(_AANHEF + ',\\s*' + _TITEL + _NAAM +
      ',[\\s\\S]{0,150}?als waarnemer van\\s*' + _TITEL + _NAAM +
      _NOTARIS_TE + _NAAM + '[:,.]', 'i'),
    maak: (m) => 'een waarnemer van mr. ' + _naarInitialen(m[2]) + ', destijds notaris te ' + m[3].trim(),
  },
  // notaris die zelf passeert
  {
    re: new RegExp(_AANHEF + ',\\s*' + _TITEL + _NAAM + _NOTARIS_TE + _NAAM + '[:,.]', 'i'),
    maak: (m) => 'mr. ' + _naarInitialen(m[1]) + ', notaris te ' + m[2].trim(),
  },
];

function _parseBrondocumentNotaris(text) {
  const t = String(text || '').replace(/\s+/g, ' ');
  for (const patroon of _NOTARIS_PATRONEN) {
    const m = t.match(patroon.re);
    if (m) return { aanhaling: patroon.maak(m) };
  }
  return null;
}

// 'Heden, dertien november tweeduizend negentien, verschenen voor mij' —
// de passeerdatum staat in het brondocument al voluit; overnemen is exacter
// dan de inschrijfdatum omrekenen (inschrijving kan later zijn).
function _parseBrondocumentDatum(text) {
  const m = String(text || '').replace(/\s+/g, ' ').match(
    /\b(?:Heden|Vandaag),\s*([a-zà-ÿ ]+?tweeduizend[a-zà-ÿ ]*?|[a-zà-ÿ ]+?negentienhonderd[a-zà-ÿ]*),\s*verschenen/i
  );
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

// De aard van de titel ('akte van levering') staat nergens in de kadastrale
// uitdraai — die noemt alleen deel, nummer en datum. Ze blijkt wél uit het
// brondocument zelf: dat draagt de kop van de akte en de operatieve zin
// waarmee geleverd of verdeeld wordt. Zonder dit bleef de aard een gele
// invulmarker in elke akte, terwijl het stuk in het dossier zit.
const _TITEL_SOORTEN = [
  // Verdeling eerst: een akte van verdeling en levering is een verdeling.
  { aard: 'verdeling', rx: /^#{1,6}\s*(?:AKTE VAN\s+)?(?:VERDELING|TOEDELING)\b|\bwordt\s+toegedeeld\s+aan\b/mi },
  { aard: 'levering', rx: /^#{1,6}\s*(?:AKTE VAN\s+)?(?:KOOP EN\s+)?LEVERING\b|\blevert\b[^.]{0,200}\baanvaardt\b/mi },
];
// Kwijting en het uitgewerkt zijn van de ontbindende voorwaarden worden in de
// akte bij de titel vermeld (het KNB-model schrijft de kwijting met zoveel
// woorden voor). Beide worden aan de operatieve zin van dít stuk herkend en
// niet aan een terugblik op een oudere akte: de paragraaf 'VOORGAANDE
// VERKRIJGING' vertelt hetzelfde over de vórige titel en zou anders een
// kwijting opleveren die in deze akte niet gegeven is.
const _KWIJTING_RX = /^#{1,6}\s*KWIJTING\b/mi;
const _KWIJTING_ZIN_RX = /\bkwiteert\b/i;
const _ONTBINDEND_RX = /^#{1,6}\s*ONTBINDENDE VOORWAARDEN\b/mi;
const _ONTBINDEND_ZIN_RX = /(?:noch\s+verkoper\s+noch\s+koper|geen\s+van\s+(?:de\s+)?partijen)[^.]{0,160}ontbindende\s+voorwaarde/i;

function _parseBrondocumentTitel(text) {
  const t = String(text || '');
  const soort = _TITEL_SOORTEN.find((s) => s.rx.test(t));
  if (!soort) return null;
  return {
    aard: soort.aard,
    kwijting: _KWIJTING_RX.test(t) || _KWIJTING_ZIN_RX.test(t),
    ontbindende_voorwaarden: _ONTBINDEND_RX.test(t) || _ONTBINDEND_ZIN_RX.test(t),
  };
}

// Brondocumenten op deel/nummer indexeren via hun bestandsnaam
// ('Brondocument 81458-165-HYP3 onroerende zaken.pdf').
// Een afschrift draagt zijn eigen inschrijvingsstempel in de tekst:
//   'Onroerende Zaken Hyp4 : 76787/180 13-11-2019 12:42'
//   '... in register Onroerende Zaken Hyp3 in deel 81458 nummer 165.'
// Verwijzingen naar ándere aktes staan er anders ('in register Hypotheken 4,
// deel ... nummer ...'), dus die komen hier niet doorheen. Zo hoeft de
// koppeling niet op de bestandsnaam te leunen.
function _stukkenUitBrondocument(text) {
  const re = /Onroerende\s+Zaken\s+Hyp\s*(\d)\s*(?::\s*(\d+)\/(\d+)|in\s+deel\s+(\d+)\s+nummer\s+(\d+))/gi;
  const t = String(text || '').replace(/\s+/g, ' ');
  const gevonden = new Map();
  let m;
  while ((m = re.exec(t)) !== null) {
    const deel = m[2] || m[4];
    const nummer = m[3] || m[5];
    if (deel && nummer) gevonden.set(deel + '/' + nummer, { deel, nummer, register: m[1] });
  }
  return [...gevonden.values()];
}

function _indexeerBrondocumenten(bronnen) {
  const index = {};
  for (const b of bronnen) {
    const uitTekst = _stukkenUitBrondocument(b.text);
    const uitNaam = String(b.filename || '').match(/(\d{3,})[-\s](\d+)[-\s]?HYP(\d)/i);
    const stukken = uitTekst.length
      ? uitTekst
      : (uitNaam ? [{ deel: uitNaam[1], nummer: uitNaam[2], register: uitNaam[3] }] : []);
    if (!stukken.length) continue;
    const gegevens = {
      notaris: _parseBrondocumentNotaris(b.text),
      datum_woorden: _parseBrondocumentDatum(b.text),
      titel: _parseBrondocumentTitel(b.text),
    };
    for (const stuk of stukken) index[stuk.deel + '/' + stuk.nummer] = { ...stuk, ...gegevens };
  }
  return index;
}

// Kadaster-uitdraaien herhalen op elke pagina een vaste kop (BETREFT ... BLAD
// n van m). Docling weeft die dwars door de inhoud, waardoor bij elkaar horende
// regels uit elkaar getrokken worden. Eerst weghalen dus.
function _stripPaginakop(text) {
  return String(text || '').replace(
    /BETREFT[\s\S]{0,800}?BLAD\s*\|?\s*\n+\s*\|?\s*\d+\s+van\s+\d+/gi, ''
  );
}

// Soorten zoals het Kadaster ze benoemt.
const _SOORT_RX = /(overdracht|verdeling|toedeling|levering|hypotheek|beslag|erfdienstbaarheid|onteigening|verjaring|fusie|splitsing|ruilverkaveling|inbreng|legaat|erfopvolging|vestiging|koop)/i;
// Uitsluiten in plaats van whitelisten. De oudere kadastrale uitdraai
// ('kadastraalberichtobject') noemt de verkrijgingssoort namelijk helemaal
// niet — die staat alleen als sectiekop '## 1 Eigendom (recht van)' boven de
// regel. Een whitelist liet daardoor élke verkrijging vallen. Alles in de
// eigendomsuitdraai telt nu als verkrijging, behalve wat aantoonbaar een
// aantekening of beperkt recht is.
// Wat als 'soort' herkend mag worden: zowel verkrijgingssoorten als de
// aantekeningen en beperkte rechten. Zonder die tweede groep blijft de soort
// bij een aantekening leeg en glipt hij door het uitsluitfilter heen.
const _SOORT_HERKEN_RX = /(overdracht|verdeling|toedeling|levering|hypotheek|beslag|erfdienstbaarheid|onteigening|verjaring|fusie|splitsing|ruilverkaveling|inbreng|legaat|erfopvolging|vestiging|koop|kwalitatieve verplichting|publiekrechtelijke|opstal|vruchtgebruik|erfpacht|gebruik en bewoning|naamswijziging|belemmeringenwet)/i;

// Beperkte rechten die het perceel bezwaren komen in de onderpandregel terug
// ('het recht van eigendom, belast met het nader te omschrijven recht van
// opstal nutsvoorzieningen, ...').
// Docling herhaalt een tabelcel soms over meerdere kolommen, waardoor dezelfde
// zin twee keer achter elkaar in de tekst belandt.
function _ontdubbelZin(tekst) {
  const t = String(tekst || '').replace(/\s+/g, ' ').trim();
  const helft = (t.length - 1) / 2;
  if (Number.isInteger(helft) && t[helft] === ' ' &&
      t.slice(0, helft) === t.slice(helft + 1)) {
    return t.slice(0, helft);
  }
  return t;
}

const _BEPERKT_RECHT_RX = /(opstal(?:recht)?[a-zà-ÿ ]*|erfpacht|vruchtgebruik|gebruik en bewoning|zakelijk recht[^|\n]*?belemmeringenwet[a-zà-ÿ ]*)/i;

// '1 Eigendom belast met Zakelijk recht ...' is een eigendomsrecord dat vermeldt
// waarmee het bezwaard is; '1.1 Zakelijk recht ...' ís dat beperkte recht. Voor
// de vraag of iets een verkrijging is telt dus alleen wat vóór 'belast met'
// staat, anders valt de eigendomsverkrijging ten onrechte af.
function _soortKern(soort) {
  return String(soort || '').split(/\bbelast met\b/i)[0];
}

const _GEEN_VERKRIJGING_RX = /(erfdienstbaarheid|kwalitatieve verplichting|publiekrechtelijke|hypotheek|beslag|opstal|vruchtgebruik|erfpacht|gebruik en bewoning|naamswijziging|belemmeringenwet)/i;

// Inschrijvingen uit een Kadaster-uitdraai. Er wordt bewust NIET op sectiekop
// ('RECHTEN') afgebakend en niet op regelpositie gerekend: Docling levert de
// markdown in wisselende volgorde — soms staat de soort vóór de
// stukverwijzing, soms erna, en '## RECHTEN' kan ná zijn eigen regels staan.
// Daarom per anker het hele venster doorzoeken en achteraf op soort filteren.
function _parseInschrijvingen(text) {
  const t = _stripPaginakop(text);
  const re = /Afkomstig\s+uit\s+stuk(?:ken)?/gi;
  const treffers = [];
  let m;
  while ((m = re.exec(t)) !== null) treffers.push({ index: m.index, eind: re.lastIndex });
  return treffers.map((tr, i) => {
    const venster = t.slice(tr.eind, i + 1 < treffers.length ? treffers[i + 1].index : t.length);
    const stuk = venster.match(/Hyp(\d)\s+(\d+)\/(\d+)/i);
    if (!stuk) return null;
    // De soort staat per uitdraai ergens anders: op de vorige regel
    // ('Opstalrecht Nutsvoorzieningen', of de kop van een aantekeningtabel),
    // op dezelfde regel vóór het anker ('Overige aantekening Kwalitatieve
    // verplichting Afkomstig uit stuk ...'), of vlak ná het anker (nieuwe
    // uitdraai). In die volgorde zoeken, en dichtbij blijven: verderop in het
    // document staat het volgende recht en dat is een andere zaak.
    const regelStart = t.lastIndexOf('\n', tr.index) + 1;
    const vorigeStart = t.lastIndexOf('\n', regelStart - 2) + 1;
    const kandidaten = [
      t.slice(regelStart, tr.index),
      t.slice(vorigeStart, regelStart),
      ...venster.split(/\r?\n/).slice(0, 6),
    ];
    let soort = '';
    for (const kandidaat of kandidaten) {
      const r = kandidaat.replace(/[|#-]/g, ' ').replace(/\s+/g, ' ').trim();
      if (r && _SOORT_HERKEN_RX.test(r) && !/^Afkomstig/i.test(r)) { soort = r; break; }
    }
    const pak = (rx) => { const x = venster.match(rx); return x ? x[1] : ''; };
    // 'Aandeel 1/2' staat vóór de stukverwijzing, niet erin: achteruit kijken
    // dus, maar nooit voorbij de vorige stukverwijzing — anders erft dit stuk
    // het aandeel van het vorige. De akte schrijft het als 'ieder voor de
    // onverdeelde helft' zodra meer gerechtigden hetzelfde stuk delen.
    const voor = t.slice(i > 0 ? treffers[i - 1].eind : Math.max(0, tr.index - 900), tr.index);
    const aandeelHits = voor.match(/Aandeel\s*\|?\s*(\d+\s*\/\s*\d+)/gi) || [];
    const aandeel = aandeelHits.length
      ? (aandeelHits[aandeelHits.length - 1].match(/(\d+)\s*\/\s*(\d+)/) || []).slice(1, 3).join('/')
      : '';
    const ingeschreven_op = pak(/Ingeschreven\s+op\s*\|?\s*(\d{2}-\d{2}-\d{4})/i);
    // Zonder inschrijfdatum valt er geen zinnige clausule te schrijven; zo'n
    // fragment is vrijwel altijd een losgeraakte verwijzing uit de scrambling.
    if (!ingeschreven_op) return null;
    return {
      register: stuk[1], deel: stuk[2], nummer: stuk[3], soort, ingeschreven_op, aandeel,
      ondertekend_op: pak(/Ondertekend\s+op\s*\|?\s*(\d{2}-\d{2}-\d{4})/i),
      // Docling plakt soms twee labels in één cel ('Ondertekend op Ingeschreven
      // bedrag | 03-12-2018 om 00:00 € 200.000'); zonder anker op het
      // euroteken werd de datum als bedrag gelezen.
      bedrag: pak(/Ingeschreven\s+bedrag[^€]{0,120}€\s*([\d][\d.,]*)/i) ||
              pak(/Ingeschreven\s+bedrag\s*\|?\s*(\d{1,3}(?:\.\d{3})+(?:,\d{2})?)/i),
      houder: pak(/Hypotheekhouder\s*\|?\s*([^|\n]+)/i).replace(/\s+/g, ' ').trim(),
      // Voor een beperkt recht: wie het recht heeft en waar die gevestigd is.
      // Het gerechtigde-veld begint soms met een stukverwijzing
      // ('Hyp4 16763/25 Rotterdam gemeente Molenlanden'); die knippen we eraf.
      gerechtigde: _ontdubbelZin(pak(/Naam\s+gerechtigde\s*\|?\s*([^|\n]+)/i))
        .replace(/^Hyp\d\s+\d+\/\d+\s+\S+\s*/i, '').trim(),
      zetel: _nettePlaatsnaam(pak(/Statutaire\s+zetel\s*\|?\s*([^|\n]+)/i)),
    };
  }).filter(Boolean)
    // Binnen het subblok van een beperkt recht ('1.1 Zakelijk recht ...') staan
    // meerdere stukverwijzingen onder één kopregel; alleen de eerste vindt die
    // kop. De rest erft de soort, zodat ze niet als verkrijging worden gelezen.
    .map((v, i, alle) => {
      if (v.soort || i === 0) return v;
      const vorige = alle[i - 1].soort;
      return _BEPERKT_RECHT_RX.test(vorige) ? { ...v, soort: vorige } : v;
    });
}

// Eén stuk kan meerdere keren opduiken: de uitdraai herhaalt de verwijzing per
// gerechtigde, en hetzelfde stuk kan zowel als aantekening als als verkrijging
// genoemd worden. Ontdubbelen gebeurt daarom ná het soortfilter, zodat de
// bruikbare vermelding overblijft en niet de eerste de beste.
function _ontdubbelStukken(lijst) {
  return lijst.filter((v, i, alle) =>
    alle.findIndex((w) => w.deel === v.deel && w.nummer === v.nummer) === i);
}

// Chronologisch op inschrijfdatum: de volgorde in het document is bij Docling
// geen betrouwbare leidraad meer.
// 'dd-mm-jjjj' -> 20260119, zodat datums als getal te vergelijken zijn. Een
// ontbrekende of onleesbare datum levert 0 op; die valt daarmee buiten elke
// vergelijking in plaats van als oudste te gelden.
function _datumSleutel(datum) {
  const m = String(datum || '').match(/(\d{2})-(\d{2})-(\d{4})/);
  return m ? Number(m[3] + m[2] + m[1]) : 0;
}

function _opDatum(a, b) {
  return _datumSleutel(a.ingeschreven_op) - _datumSleutel(b.ingeschreven_op);
}

// --- Deterministische kadastergegevens, per perceel ----------------------
// Een dossier kan meerdere percelen omvatten (bijvoorbeeld een woonhuis plus
// een los perceel grond). Het Kadaster levert per perceel een eigen eigendoms-
// en hypotheekinformatie; we groeperen de bronnen op kadastrale aanduiding en
// houden per perceel de meest recente uitdraai aan. Verkrijging én
// voorbelasting verschillen per perceel en horen dus in die groepering thuis.
const _bronnen = _splitKadasterBronnen(kadaster_markdown);
const _brondocs = _indexeerBrondocumenten(_bronnen);

function _verrijkMetBrondocument(v) {
  const bron = _brondocs[v.deel + '/' + v.nummer];
  const titel = (bron && bron.titel) || null;
  return {
    ...v,
    notaris: (bron && bron.notaris && bron.notaris.aanhaling) || '',
    datum_woorden: (bron && bron.datum_woorden) || '',
    // Zonder brondocument valt de aard terug op wat het Kadaster zelf als
    // soort noteert; ontbreekt ook dat, dan blijft het een invulmarker.
    titel_aard: (titel && titel.aard) || _titelAardUitSoort(v.soort),
    titel_kwijting: Boolean(titel && titel.kwijting),
    titel_ontbindende_voorwaarden: Boolean(titel && titel.ontbindende_voorwaarden),
  };
}

function _titelAardUitSoort(soort) {
  const s = String(soort || '').toLowerCase();
  if (/verdeling/.test(s)) return 'verdeling';
  if (/toedeling/.test(s)) return 'toedeling';
  if (/levering|koop|overdracht/.test(s)) return 'levering';
  return '';
}

// Dezelfde stukverwijzing staat in de uitdraai één keer per gerechtigde
// ('Aandeel 1/2' bij ieder van beide echtgenoten). Na het ontdubbelen is die
// telling weg, terwijl de akte er 'ieder voor de onverdeelde helft' op
// baseert; daarom vóór het ontdubbelen tellen.
function _metGerechtigden(lijst) {
  const aantallen = new Map();
  for (const v of lijst) {
    const k = v.deel + '/' + v.nummer;
    aantallen.set(k, (aantallen.get(k) || 0) + 1);
  }
  return _ontdubbelStukken(lijst).map(
    (v) => ({ ...v, gerechtigden: aantallen.get(v.deel + '/' + v.nummer) || 1 })
  );
}

// 'Omschrijving | Wonen' of 'Perceel grond - gebruik onbekend': bepaalt of het
// perceel als woonhuis of als perceel grond wordt omschreven.
// Een samengevoegd perceel vermeldt onder 'Ontstaan uit' de percelen waaruit
// het is ontstaan. Die oude nummers staan vaak nog als eigen uitdraai in het
// dossier, maar ze bestaan kadastraal niet meer en horen niet in de akte.
function _parseOntstaanUit(text) {
  const t = String(text || '');
  const m = t.match(/Ontstaan\s+uit/i);
  if (!m) return [];
  // Bij een samenvoeging uit meerdere percelen staat het label één keer en
  // volgen de overige percelen als tabelrijen met een lege labelkolom. Doorlezen
  // tot een regel die zelf weer een label draagt.
  const regels = t.slice(m.index).split(/\r?\n/);
  const blok = [regels[0]];
  for (const regel of regels.slice(1)) {
    const cellen = regel.split('|');
    if (cellen.length < 2) break;
    if (cellen[1].trim()) break;
    blok.push(regel);
  }
  const uit = [];
  const re = /([A-Za-zÀ-ÿ.'’ -]+?)\s+([A-Z]{1,2})\s+(\d+)\b/g;
  let g;
  while ((g = re.exec(blok.join(' ').replace(/Ontstaan\s+uit/i, '').replace(/\s+/g, ' '))) !== null) {
    uit.push([g[1].trim(), g[2], g[3]].join('|'));
  }
  return uit;
}

function _parseOmschrijving(text) {
  const m = String(text || '').match(/Omschrijving\s*\|?\s*([^|\n]+)/i);
  return m ? m[1].replace(/\s+/g, ' ').trim() : '';
}

// Kadaster-downloads dragen het perceel in hun bestandsnaam:
//   'Eigendomsinformatie Capelle aan den IJssel D 4057 - 28-01-2026 10_42.pdf'
//   'kadastraalberichtobject Hoornaar-A-291 (2).pdf'
// Dat is betrouwbaarder dan de inhoud: Docling rendert de ALGEMEEN-tabel van
// het ene product als markdown-tabel en van het andere als losse labelregels
// zonder waarden, dus per bron parsen levert wisselend niets op.
const _PRODUCTNAMEN_RX = /^(?:kadastraalberichtobject|hypothecairberichtobject|eigendomsinformatie|hypotheekinformatie|uittrekselkadastralekaart|objectlijst\w*)\s*/i;

// De kadastrale aanduiding komt uit de inhoud, niet uit de bestandsnaam: een
// dossier kan hernoemde downloads bevatten en dan zou het onderpand in de akte
// meeveranderen. 'BETREFT' staat op elke pagina van elke Kadaster-uitdraai en
// is daarmee de betrouwbaarste bron; 'Kadastrale aanduiding' is de tweede.
function _perceelUitTekst(text) {
  const t = String(text || '');
  for (const re of [/BETREFT\s*\|?\s*\n*\s*\|?\s*([^\n|]+)/i,
                    /Kadastrale\s+aanduiding\s*\|?\s*([^\n|]+)/i]) {
    const m = t.match(re);
    if (!m) continue;
    const aand = _splitsAanduiding(m[1]);
    if (aand) return aand;
  }
  return null;
}

// 'Capelle aan den IJssel D 4057' -> gemeente/sectie/nummer.
function _splitsAanduiding(ruw) {
  const m = String(ruw || '').replace(/\s+/g, ' ').trim()
    .match(/^([A-Za-zÀ-ÿ.'’ -]+?)\s+([A-Z]{1,2})\s+(\d+)\b/);
  if (!m) return null;
  return {
    kadastrale_gemeente: m[1].trim(),
    kadastrale_sectie: m[2],
    kadastrale_nummer: m[3],
  };
}

function _perceelUitBestandsnaam(filename) {
  // Underscores gelijkstellen aan spaties: bestandsnamen worden onderweg vaak
  // 'geschoond' en dan is 'Eigendomsinformatie_Capelle_aan_den_IJssel_D_4057'
  // net zo goed een geldige aanduiding.
  const f = String(filename || '').replace(/\.[a-z0-9]+$/i, '')
    .replace(/_/g, ' ').replace(/\s+/g, ' ').trim().replace(_PRODUCTNAMEN_RX, '');
  let m = f.match(/^([A-Za-zÀ-ÿ.'’ ]+?)-([A-Z]{1,2})-(\d+)\b/);
  if (!m) m = f.match(/^([A-Za-zÀ-ÿ.'’ ]+?)\s+([A-Z]{1,2})\s+(\d+)\b/);
  if (!m) return null;
  return {
    kadastrale_gemeente: m[1].replace(/\s+/g, ' ').trim(),
    kadastrale_sectie: m[2],
    kadastrale_nummer: m[3],
  };
}

// Heeft dit perceel een eigen BAG-locatie (huisnummer)? Zo niet, dan is het een
// los perceel grond en schrijft de akte 'gelegen nabij' in plaats van
// 'staande en gelegen te'.
function _heeftEigenLocatie(text) {
  const m = String(text || '').match(/Locatie\s*\|?\s*([^|\n]*)/i);
  return Boolean(m && /\d/.test(m[1]));
}

function _bronSoort(bron) {
  // Elke uitdraai draagt zijn producttitel in de tekst ('## Hypotheekinformatie');
  // de bestandsnaam is ook hier alleen terugval.
  if (/Hypotheekinformatie/.test(bron.text) ||
      /Hypotheekinformatie|hypothecairbericht/i.test(bron.filename)) return 'hypotheek';
  if (/Eigendomsinformatie/.test(bron.text) ||
      /Eigendomsinformatie|kadastraalbericht/i.test(bron.filename)) return 'eigendom';
  return null;
}

function _verzamelPercelen(bronnen) {
  const perPerceel = new Map();
  for (const bron of bronnen) {
    // Inhoud gaat vóór bestandsnaam; die laatste is alleen een laatste redmiddel
    // als Docling de uitdraai onleesbaar heeft gerenderd.
    const aand = _perceelUitTekst(bron.text) || _perceelUitBestandsnaam(bron.filename);
    const soort = _bronSoort(bron);
    if (!aand || !soort) continue;
    const sleutel = [aand.kadastrale_gemeente, aand.kadastrale_sectie, aand.kadastrale_nummer].join('|');
    if (!perPerceel.has(sleutel)) {
      perPerceel.set(sleutel, { aanduiding: aand, eigendom: null, hypotheek: null });
    }
    const rij = perPerceel.get(sleutel);
    if (!rij[soort] || _geleverdOp(bron.text) > _geleverdOp(rij[soort].text)) rij[soort] = bron;
  }
  return [...perPerceel.values()];
}

const _percelen = _verzamelPercelen(_bronnen)
  .map((p) => {
    const eig = p.eigendom;
    const hyp = p.hypotheek;
    // Een los perceel grond heeft geen eigen BAG-locatie. Dat onderscheid
    // bepaalt of de akte 'staande en gelegen te' of 'gelegen nabij' schrijft.
    const eigenLocatie = Boolean((eig && _heeftEigenLocatie(eig.text)) ||
                                 (hyp && _heeftEigenLocatie(hyp.text)));
    return {
      gemeente: p.aanduiding.kadastrale_gemeente,
      sectie: p.aanduiding.kadastrale_sectie,
      nummer: p.aanduiding.kadastrale_nummer,
      grootte_m2: eig ? _parseKadastraleGrootte(eig.text) : '',
      // adres wordt hieronder uit _detAdres ingevuld
      omschrijving: eig ? _parseOmschrijving(eig.text) : '',
      ontstaan_uit: eig ? _parseOntstaanUit(eig.text) : [],
      eigen_locatie: eigenLocatie,
      straat: '', huisnummer: '', postcode: '', woonplaats: '',
      hypotheekinformatie_aanwezig: Boolean(hyp),
      // Een beperkt recht komt in de onderpandregel terug ('belast met het nader
      // te omschrijven ...') én verderop in een eigen omschrijving met de
      // rechthebbende erbij. Zonder die tweede belooft de akte iets wat er niet
      // staat, dus houder en zetel gaan mee.
      beperkte_rechten: (() => {
        const gezien = new Set();
        return (eig ? _parseInschrijvingen(eig.text) : [])
          .filter((v) => !/\bbelast met\b/i.test(v.soort))
          .map((v) => ({
            soort: _ontdubbelZin((v.soort.match(_BEPERKT_RECHT_RX) || [''])[0]),
            houder: v.gerechtigde || '',
            zetel: v.zetel || '',
          }))
          // Van dezelfde soort de vermelding houden die de rechthebbende noemt:
          // de eerste stukverwijzing in een subblok heeft die vaak nog niet.
          .sort((a, b) => (b.houder ? 1 : 0) - (a.houder ? 1 : 0))
          .filter((r) => {
            if (!r.soort || gezien.has(r.soort.toLowerCase())) return false;
            gezien.add(r.soort.toLowerCase());
            return true;
          });
      })(),
      verkrijgingen: _metGerechtigden(
        (eig ? _parseInschrijvingen(eig.text) : [])
          .filter((v) => !_GEEN_VERKRIJGING_RX.test(_soortKern(v.soort))))
        .sort(_opDatum)
        .map(_verrijkMetBrondocument),
      // In een hypothecaire uitdraai is elke 'Afkomstig uit stuk' per definitie
      // een hypotheek of beslag; daar is geen soortfilter voor nodig (en de
      // soort komt er in de oude opmaak toch niet betrouwbaar uit).
      voorbelasting: _ontdubbelStukken(hyp ? _parseInschrijvingen(hyp.text) : [])
        .sort(_opDatum)
        .map(_verrijkMetBrondocument),
    };
  })
  // Het perceel met een eigen adres is het hoofdperceel en komt als 'a.' eerst;
  // losse percelen grond volgen op sectie en nummer.
  .sort((a, b) =>
    (Number(b.eigen_locatie) - Number(a.eigen_locatie)) ||
    a.sectie.localeCompare(b.sectie) ||
    (Number(a.nummer) - Number(b.nummer)));

// Percelen die zijn opgegaan in een samenvoeging horen niet in de akte: het
// dossier bevat hun oude uitdraaien nog, maar kadastraal bestaan ze niet meer.
// Vervallen perceel -> opvolger, zodat de titelketen niet met het perceel
// verdwijnt: de oudere verkrijging staat ingeschreven op het perceel van vóór
// de samenvoeging en hoort nog steeds in de akte.
const _opvolger = new Map();
for (const p of _percelen) {
  for (const sleutel of p.ontstaan_uit || []) _opvolger.set(sleutel, p);
}
const _actievePercelen = _percelen.filter(
  (p) => !_opvolger.has([p.gemeente, p.sectie, p.nummer].join('|'))
);
for (const p of _percelen) {
  const doel = _opvolger.get([p.gemeente, p.sectie, p.nummer].join('|'));
  if (!doel) continue;
  doel.verkrijgingen = _ontdubbelStukken([...doel.verkrijgingen, ...p.verkrijgingen]).sort(_opDatum);
  doel.voorbelasting = _ontdubbelStukken([...doel.voorbelasting, ...p.voorbelasting]).sort(_opDatum);
}
// Blijft er niets over, dan klopt de aanname niet en houden we de hele lijst
// aan; een lege onderpandlijst is erger dan een perceel te veel.
if (_actievePercelen.length) _percelen.splice(0, _percelen.length, ..._actievePercelen);

// Het onderpandadres komt uit de hele kadasterblob (_detAdres, hierboven): per
// losse bron is het bij Docling niet betrouwbaar te vinden. Percelen zonder
// eigen locatie krijgen datzelfde adres, maar worden als 'gelegen nabij'
// omschreven — precies zoals in de modelakte.

for (const p of _percelen) {
  p.straat = (_detAdres && _detAdres.onderpand_straat) || '';
  p.huisnummer = (_detAdres && _detAdres.onderpand_huisnummer) || '';
  p.postcode = (_detAdres && _detAdres.onderpand_postcode) || '';
  p.woonplaats = (_detAdres && _detAdres.onderpand_woonplaats) || '';
}


// Het eerste perceel vult de losse <<KAD_*>>- en <<ONDERPAND_*>>-placeholders.
// Die blijven bestaan: het ABN AMRO-template gebruikt ze en kent (nog) geen
// meervoudige percelen.
if (_percelen.length) {
  const p0 = _percelen[0];
  Object.assign(data.kadaster, {
    kadastrale_gemeente: p0.gemeente,
    kadastrale_sectie: p0.sectie,
    kadastrale_nummer: p0.nummer,
  });
  if (p0.grootte_m2) data.kadaster.kadastrale_grootte_m2 = p0.grootte_m2;
  if (p0.straat) {
    Object.assign(data.kadaster, {
      onderpand_straat: p0.straat,
      onderpand_huisnummer: p0.huisnummer,
      onderpand_postcode: p0.postcode,
      onderpand_woonplaats: p0.woonplaats,
    });
  }
}

// Ontbreekt voor één van de percelen de hypothecaire informatie, dan wéten we
// niet of het onbezwaard is — en dan mag de akte dat niet verklaren.
const _voorbelastingBekend = _percelen.length > 0 &&
  _percelen.every((p) => p.hypotheekinformatie_aanwezig);
const _heeftVoorbelasting = _percelen.some((p) => p.voorbelasting.length > 0);

// --- Uiterlijke passeerdatum (aktedatum) uit de passeeropdracht ---
// De akte moet vóór de in de passeeropdracht genoemde uiterlijke datum passeren;
// die datum gebruiken we als aktedatum. Deterministisch parsen (niet via de LLM).
// Het Python-vulscript zet de rauwe datum om naar voluit ('zeven april
// tweeduizend tweeentwintig') via <<AKTE_DATUM_RAW>> -> <<AKTE_DATUM>>.
function _parseUiterlijkeDatum(md) {
  const t = String(md || '');
  // Rabobank: "De akte dient voor DD-MM-JJJJ te worden gepasseerd"
  let m = t.match(/akte\s+dient\s+voor\s+(\d{1,2}-\d{1,2}-\d{4})\s+te\s+worden\s+gepasseerd/i);
  if (m) return m[1];
  m = t.match(/geldigheidsduur\s+van\s+de\s+offerte\s+is\s+mogelijk\s+tot\s+(\d{1,2}-\d{1,2}-\d{4})/i);
  if (m) return m[1];
  // ABN AMRO / Stater: "De offerte is geldig tot en met D maandnaam JJJJ" (datum in woorden)
  const MAAND = { januari: '01', februari: '02', maart: '03', april: '04', mei: '05', juni: '06', juli: '07', augustus: '08', september: '09', oktober: '10', november: '11', december: '12' };
  m = t.match(/offerte\s+is\s+geldig\s+tot\s+en\s+met\s+(\d{1,2})\s+([a-zA-Z]+)\s+(\d{4})/i);
  if (m) {
    const mm = MAAND[m[2].toLowerCase()];
    if (mm) return ('0' + m[1]).slice(-2) + '-' + mm + '-' + m[3];
  }
  return '';
}
const _uiterlijk = _parseUiterlijkeDatum(bank_markdown);
if (_uiterlijk) data.bank.akte_uiterlijke_datum = _uiterlijk;

function getPath(obj, path) {
  const parts = String(path).split(/\.|\[|\]/).filter(Boolean);
  let cur = obj;
  for (const part of parts) {
    if (cur == null) return undefined;
    const idx = /^\d+$/.test(part) ? parseInt(part, 10) : part;
    cur = cur[idx];
  }
  return cur;
}

function isTruthyValue(v) {
  if (v == null) return false;
  if (typeof v === 'boolean') return v;
  if (typeof v === 'number') return v !== 0;
  const s = String(v).trim().toLowerCase();
  if (!s) return false;
  return ['true', '1', 'yes', 'ja', 'y', 't'].includes(s);
}

const placeholderMap = bankConfig.placeholders || {};
const placeholders = {};
for (const [tag, paths] of Object.entries(placeholderMap)) {
  let value = '';
  const candidatePaths = Array.isArray(paths) ? paths : [paths];
  for (const p of candidatePaths) {
    const v = getPath(data, p);
    // Alleen scalars: een array/object dat per ongeluk uit de extractie komt
    // zou anders als '[object Object]' in de akte belanden. Sla die over zodat
    // een volgende (betrouwbare) bron of leegwaarde wordt gebruikt.
    if ((typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean') && String(v).trim() !== '') {
      value = String(v);
      break;
    }
  }
  placeholders[tag] = value;
}

// --- Kantoor-instellingen (notaris, standplaats) uit kantoor.json ---
// Kantoor-specifieke standaardwaarden staan LOS van de template-registry, zodat
// verschillende notariskantoren hun eigen notaris(sen) en slotteksten beheren
// (later via de webapp-instellingen). Ontbreekt het bestand of een veld, dan
// blijft de betreffende placeholder leeg (handmatig in te vullen).
try {
  const kantoor = JSON.parse(fs.readFileSync('/data/shared/kantoor.json', 'utf8'));
  if (kantoor && typeof kantoor === 'object') {
    if (kantoor.notaris_naam) placeholders['<<NOTARIS_NAAM>>'] = String(kantoor.notaris_naam);
    if (kantoor.notaris_standplaats) placeholders['<<NOTARIS_STANDPLAATS>>'] = String(kantoor.notaris_standplaats);
    if (kantoor.kantoor_naam) placeholders['<<KANTOOR_NAAM>>'] = String(kantoor.kantoor_naam);
    if (kantoor.bank_volmachthouder) placeholders['<<BANK_VOLMACHTHOUDER>>'] = String(kantoor.bank_volmachthouder);
    // Volmacht-/rectificatie-/bijlagenblok vlak vóór het slot; net als de
    // slottekst een lijst regels die het vulscript tot paragrafen expandeert.
    if (Array.isArray(kantoor.volmacht_tekst)) placeholders['<<VOLMACHT_TEKST>>'] = kantoor.volmacht_tekst.join('\n');
    else if (kantoor.volmacht_tekst) placeholders['<<VOLMACHT_TEKST>>'] = String(kantoor.volmacht_tekst);
    // Slottekst: lijst regels -> newline-string; het vulscript expandeert die
    // op de <<SLOT_TEKST>>-marker naar losse paragrafen.
    if (Array.isArray(kantoor.slot_tekst)) placeholders['<<SLOT_TEKST>>'] = kantoor.slot_tekst.join('\n');
    else if (kantoor.slot_tekst) placeholders['<<SLOT_TEKST>>'] = String(kantoor.slot_tekst);
  }
} catch (e) {
  console.error('[Build Placeholders] kantoor.json niet gelezen:', e && e.message);
}

// Bank-volmachthouder wisselt per akte en staat (nog) niet in de config:
// toon een invul-hint zodat het veld zichtbaar en gearceerd is in de akte.
if (!String(placeholders['<<BANK_VOLMACHTHOUDER>>'] || '').trim()) {
  placeholders['<<BANK_VOLMACHTHOUDER>>'] = '[gevolmachtigde bank \u2014 invullen]';
}

// --- Burgerlijke staat: echtpaar/partners -> gecombineerde clausule ---
// Bij een gehuwd/geregistreerd-partner-paar dat samen het onderpand verkrijgt,
// vervalt het individuele "wonende te" per persoon en komt er één clausule
// "[regime] gehuwd, tezamen wonende te <adres>". Het regime (met/zonder
// huwelijkse voorwaarden) staat NIET in de stukken en blijft een in te vullen
// blanco. Bron burgerlijke staat: kadasterveld bij de gerechtigde.
const _kl = Array.isArray(data.kadaster.klanten) ? data.kadaster.klanten : [];
const _bs = String((_kl[0] && _kl[0].burgerlijke_staat) || '').toLowerCase();
// De BRP geeft de HUIDIGE burgerlijke staat; het kadasterveld geldt uitsluitend
// 'ten tijde van verkrijging' en kan tientallen jaren achterlopen. In 2021.0588
// staat de eigenaar bij zijn verkrijging uit 2009 als ongehuwd, terwijl hij
// sinds 2011 gehuwd is met de medecomparante — en alleen zij tweeën zijn
// comparant. Noemen twee comparanten elkaar in de BRP als partner, dan is dat
// doorslaggevend; het kadaster is enkel terugval.
const _brpHuwelijk = _huwelijkTussenComparanten(_kl, _brpPersonen);
const _isPaar = _kl.length >= 2 &&
  (!!_brpHuwelijk || /gehuwd|geregistreerd\s*partner/.test(_bs));
const _adres = [
  [placeholders['<<ONDERPAND_POSTCODE>>'], placeholders['<<ONDERPAND_WOONPLAATS>>']].filter(Boolean).join(' '),
  [placeholders['<<ONDERPAND_STRAAT>>'], placeholders['<<ONDERPAND_HUISNUMMER>>']].filter(Boolean).join(' '),
].filter(Boolean).join(', ');
const _woonzin = _adres ? ('wonende te ' + _adres + ', ') : '';
if (_isPaar) {
  const _soortVerbintenis = _brpHuwelijk ? String(_brpHuwelijk.soort_verbintenis || '').toLowerCase() : '';
  const _isPartnerschap = _soortVerbintenis
    ? /geregistreerd/.test(_soortVerbintenis)
    : /geregistreerd\s*partner/.test(_bs);
  const _staatWoord = _isPartnerschap ? 'als geregistreerde partners geregistreerd' : 'gehuwd';
  placeholders['<<WOONADRES_1>>'] = '';
  placeholders['<<WOONADRES_2>>'] = '';
  // regime als in te vullen blanco: notaris kiest 'zonder'/'onder' na BRP-check
  // Het uittreksel huwelijksgoederenregister zegt of er huwelijkse voorwaarden
  // zijn gemaakt; staat dat stuk niet in het dossier, dan blijft '[zonder/onder]'
  // een bewuste blanco voor de notaris.
  const _regime = _parseHuwelijksregime(kadaster_markdown);
  placeholders['<<BURGERLIJKE_STAAT>>'] = (_regime || '[zonder/onder]') +
    ' het maken van huwelijkse voorwaarden ' + _staatWoord + ', tezamen ' + _woonzin;
  placeholders['<<#FLAG:gehuwd_samen>>'] = 'true';
} else {
  // Ook zonder echtpaar hoort de burgerlijke staat in de comparitie ('ongehuwd
  // en niet geregistreerd als partner'); die viel eerder helemaal weg. Bron is
  // hetzelfde kadasterveld dat hierboven al bepaalt of het om een paar gaat.
  function _burgerlijkeStaatZin(ruw) {
    const s = String(ruw || '').toLowerCase().replace(/\s+/g, ' ').trim();
    if (!s) return '';
    if (/ongehuwd en geen geregistreerd partnerschap/.test(s)) {
      return 'ongehuwd en niet geregistreerd als partner';
    }
    return s;
  }
  const _staat1 = _burgerlijkeStaatZin(_kl[0] && _kl[0].burgerlijke_staat);
  const _staat2 = _burgerlijkeStaatZin(_kl[1] && _kl[1].burgerlijke_staat);
  placeholders['<<WOONADRES_1>>'] = (_staat1 ? _staat1 + ', ' : '') + _woonzin;
  placeholders['<<WOONADRES_2>>'] = (_staat2 ? _staat2 + ', ' : '') + _woonzin;
  placeholders['<<BURGERLIJKE_STAAT>>'] = '';
  placeholders['<<#FLAG:gehuwd_samen>>'] = 'false';
}

const conditionalBlocks = bankConfig.conditional_blocks || {};
for (const [blockName, paths] of Object.entries(conditionalBlocks)) {
  const candidatePaths = Array.isArray(paths) ? paths : [paths];
  let active = false;
  for (const p of candidatePaths) {
    const v = getPath(data, p);
    if (typeof v === 'boolean') { active = v; if (v) break; continue; }
    if (v != null && String(v).trim() !== '') {
      const s = String(v).trim().toLowerCase();
      if (['true', 'false', '1', '0', 'yes', 'no', 'ja', 'nee'].includes(s)) {
        if (isTruthyValue(v)) { active = true; break; }
      } else {
        active = true;
        break;
      }
    }
  }
  placeholders[`<<#FLAG:${blockName}>>`] = active ? 'true' : 'false';
}

// Voorbelasting en verkrijging gaan als ruwe feiten naar het Python-vulscript;
// dat maakt er de Nederlandse akte-zinnen van (getallen en datums naar woorden).

// ============================================================================
// Beschikkingsbevoegdheid
// ----------------------------------------------------------------------------
// Toetst of de comparanten bevoegd zijn het registergoed te bezwaren, op grond
// van uitsluitend kadaster, BRP en de aankomsttitels/brondocumenten. Geen LLM:
// dit is een juridisch oordeel op gestructureerde feiten, en een stellige maar
// ongetoetste bewering is precies de faalvorm die we hier willen uitsluiten.
//
// Twee richtingen wegen verschillend:
//   - een rechthebbende die GEEN comparant is  -> kritiek (hij moet meetekenen)
//   - een comparant die GEEN rechthebbende is  -> normaal (medeschuldenaar /
//     derdehypotheekgever); alleen ter informatie.
// ============================================================================

// Een overledene blijkt nooit uit een kadastraal veld: het kadaster kent geen
// 'overleden'. Hij blijkt uit de tekst van een brondocument (verklaring van
// erfrecht) of uit de BRP van de langstlevende. We lezen beide.
function _parseOverlijdenssignalen(bronnen) {
  const uit = [];
  for (const b of (bronnen || [])) {
    const tekst = String((b && b.text) || '');
    if (!/overleden|erflater|nalatenschap|verklaring van erfrecht/i.test(tekst)) continue;
    const namen = [];
    const re = /overleden\s+(?:de\s+heer|mevrouw)\s+([A-ZÀ-Ý][A-ZÀ-Ý'’\- ]{3,60}?)\s*(?:,|\.|\n|$)/g;
    let m;
    while ((m = re.exec(tekst)) !== null) {
      const naam = m[1].replace(/\s+/g, ' ').trim();
      if (naam && !namen.includes(naam)) namen.push(naam);
    }
    const zin = (tekst.match(/[^.\n]*\boverleden\b[^.\n]*\./) || [''])[0].replace(/\s+/g, ' ').trim();
    uit.push({
      bestand: (b && b.filename) || '',
      namen,
      verklaring_van_erfrecht: /verklaring van erfrecht/i.test(tekst),
      citaat: zin.slice(0, 300),
    });
  }
  return uit;
}

// Het uittreksel huwelijksgoederenregister zegt of er huwelijkse voorwaarden
// zijn gemaakt. Alleen een uitdrukkelijke registratie vullen we in; ontbreekt
// het stuk, dan blijft '[zonder/onder]' een bewuste blanco voor de notaris.
function _parseHuwelijksregime(md) {
  const t = String(md || '');
  if (!/huwelijksgoederenregister/i.test(t)) return '';
  // Let op: anker op het volledige label. Een los 'registratie' treft eerst
  // 'Basisregistratie Kadaster' elders in de uitdraai.
  const re = /\(Meest recente\)\s*registratie\s*:?\s*\|?\s*\n{0,3}\s*([^\n|]{0,60})/gi;
  let m;
  while ((m = re.exec(t)) !== null) {
    if (/huwelijk\w*\s*voorwaarden/i.test(m[1] || '')) return 'onder';
  }
  return '';
}

// Noemen twee comparanten elkaar in de BRP als partner? De BRP geeft de
// HUIDIGE staat; het kadasterveld geldt alleen ten tijde van verkrijging.
function _huwelijkTussenComparanten(kl, brpPersonen) {
  if (!Array.isArray(kl) || kl.length < 2) return null;
  const namen = kl.map((k) => _achternaamSleutel(k.volledige_naam)).filter(Boolean);
  for (const p of (brpPersonen || [])) {
    const h = p && p.huwelijk;
    if (!h || !h.actueel || !h.partner_naam) continue;
    const zelf = _achternaamSleutel(p.volledige_naam);
    const partner = _achternaamSleutel(h.partner_naam);
    if (zelf && partner && namen.includes(zelf) && namen.includes(partner)) return h;
  }
  return null;
}

function _somAandelen(delen) {
  // Alleen exacte breuken; bij twijfel geven we null terug en oordelen we niet.
  let teller = 0, noemer = 0;
  for (const d of delen) {
    const m = String(d || '').match(/^(\d+)\/(\d+)$/);
    if (!m) return null;
    const t = Number(m[1]), n = Number(m[2]);
    if (!n) return null;
    if (!noemer) { teller = t; noemer = n; continue; }
    teller = teller * n + t * noemer;
    noemer = noemer * n;
  }
  return noemer ? teller / noemer : null;
}

// Vergelijkt twee persoonsnamen strenger dan alleen de achternaam. Nodig omdat
// een weduwe vaak de achternaam van haar overleden man draagt: 'Anna Schmidt'
// naast erflater 'Teunis Schmidt' mag geen treffer geven, anders blokkeert een
// schoon dossier. Eist gelijke achternaam én gelijke voornaam (of een initiaal
// die daarop past).
function _zelfdePersoon(a, b) {
  const norm = (s) => String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z. ]/g, ' ').replace(/\s+/g, ' ').trim();
  const ta = norm(a).split(' ').filter(Boolean);
  const tb = norm(b).split(' ').filter(Boolean);
  if (ta.length < 2 || tb.length < 2) return false;
  if (ta[ta.length - 1] !== tb[tb.length - 1]) return false;
  // Initialen komen zowel los ('P.') als aaneengeschreven ('P.J.') voor.
  const isInitiaal = (t) => t.includes('.') || t.length === 1;
  const kern = (t) => t.replace(/\./g, '');
  if (isInitiaal(ta[0]) || isInitiaal(tb[0])) {
    return !!kern(ta[0])[0] && kern(ta[0])[0] === kern(tb[0])[0];
  }
  return kern(ta[0]) === kern(tb[0]);
}

// De kadastrale burgerlijke staat komt in een handvol vaste bewoordingen voor:
// 'Gehuwd', 'Ongehuwd en geen geregistreerd partnerschap', 'Zie akte(n)' of
// leeg. Voor het vergelijken van twee verkrijgingen telt alleen de kern, anders
// leest een andere formulering in een oudere uitdraai al als een gewijzigde
// staat. 'Zie akte(n)' en een lege cel zijn geen staat en leveren '' op.
function _staatKern(staat) {
  const s = String(staat || '').toLowerCase();
  if (!s || /zie akte/.test(s)) return '';
  if (/weduw/.test(s)) return 'weduwe/weduwnaar';
  if (/gescheiden/.test(s)) return 'gescheiden';
  // Volgorde is hier wezenlijk: 'ongehuwd en geen geregistreerd partnerschap'
  // bevat zowel 'gehuwd' als 'geregistreerd partner' als deelstring.
  if (/ongehuwd|niet gehuwd/.test(s)) return 'ongehuwd';
  if (/geregistreerd partner/.test(s)) return 'geregistreerd partnerschap';
  if (/gehuwd/.test(s)) return 'gehuwd';
  return '';
}

function _beoordeelBeschikkingsbevoegdheid(kl, brpPersonen, overlijdens, percelen) {
  const punten = [];
  const onderbouwing = [];
  const rechthebbenden = kl.filter((k) => k.is_rechthebbende !== false);
  const enkelComparant = kl.filter((k) => k.is_rechthebbende === false);
  let status = 'rond';

  const zetNiet = (s) => { if (s === 'niet_rond' || status === 'rond') status = s; };

  if (!rechthebbenden.length) {
    zetNiet('onbekend');
    punten.push({
      id: 'bevoegdheid-geen-rechthebbende',
      ernst: 'aandacht',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Geen rechthebbende uit het kadaster herleid',
      constatering: 'In de kadastrale eigendomsinformatie is geen enkele "Naam gerechtigde" herkend.',
      juridisch_kader: 'Zonder vastgestelde rechthebbende kan de beschikkingsbevoegdheid niet worden getoetst (art. 3:84 jo. 3:98 BW).',
      actie: 'Controleer de eigendomsinformatie handmatig en stel de rechthebbende(n) vast.',
      bronnen: ['kadaster'],
    });
  } else {
    onderbouwing.push({
      bron: 'kadaster',
      constatering: 'Rechthebbende(n): ' + rechthebbenden.map((r) => r.volledige_naam).join(', ') + '.',
    });
  }

  // --- Overledene die nog als rechthebbende staat: de gevaarlijke variant ---
  const overledenNamen = [];
  for (const o of (overlijdens || [])) for (const n of o.namen) overledenNamen.push({ naam: n, bron: o });
  for (const r of rechthebbenden) {
    const treffer = overledenNamen.find((o) => _zelfdePersoon(o.naam, r.volledige_naam));
    if (!treffer) continue;
    zetNiet('niet_rond');
    punten.push({
      id: 'bevoegdheid-overleden-rechthebbende',
      ernst: 'kritiek',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Rechthebbende is blijkens de stukken overleden',
      constatering: `Het kadaster vermeldt ${r.volledige_naam} nog als rechthebbende, terwijl "${treffer.bron.bestand}" vermeldt: "${treffer.bron.citaat}"`,
      juridisch_kader: 'Een overledene kan niet beschikken; de nalatenschap gaat onder algemene titel over op de erfgenamen (art. 4:182 BW). Zij zijn beschikkingsbevoegd, mits bevoegd vertegenwoordigd.',
      actie: 'Stel de erfgenamen vast aan de hand van een verklaring van erfrecht en laat hen meetekenen of zich rechtsgeldig vertegenwoordigen.',
      bronnen: ['kadaster'],
    });
  }

  // --- Vererving in de titelketen die het kadaster al heeft verwerkt ---
  // Dit blokkeert niet: de overdracht is ingeschreven en de erfgenaam staat als
  // rechthebbende. Het blijft wel het vermelden waard.
  if (!punten.some((p) => p.id === 'bevoegdheid-overleden-rechthebbende')) {
    for (const o of (overlijdens || [])) {
      if (!o.namen.length && !o.verklaring_van_erfrecht) continue;
      punten.push({
        id: 'bevoegdheid-vererving-in-keten',
        ernst: 'aandacht',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Aankomsttitel loopt via een nalatenschap',
        constatering: `"${o.bestand}" vermeldt: "${o.citaat}"`,
        juridisch_kader: 'Verkrijging krachtens erfopvolging is een verkrijging onder algemene titel (art. 4:182 BW). Het kadaster vermeldt de huidige rechthebbende, maar de omvang van de verkrijging volgt uit de verklaring van erfrecht.',
        actie: 'Controleer de verklaring van erfrecht in het dossier en stel vast dat de nalatenschap volledig is afgewikkeld ten aanzien van dit registergoed.',
        bronnen: ['kadaster'],
      });
      break;
    }
  }

  // --- Rechthebbende die geen comparant is ---
  // BEWUST NIET deterministisch getoetst. De enige beschikbare bron voor 'wie
  // noemt de bankopdracht' is de LLM-extractie van de passeeropdracht, en die is
  // daarvoor te onbetrouwbaar: in 2021.1044 leverde zij naam_hoofdletters
  // "MEVROUW" op, wat een kritiek oordeel zou opleveren over een volstrekt
  // schoon dossier — precies de valse stelligheid die deze controle moet
  // uitbannen. De bestaande checks 'klantentelling-mismatch' en
  // 'achternaam-mismatch' in Deterministic Checks dekken hetzelfde signaal en
  // laten het oordeel over de bevoegdheid ongemoeid.

  // --- Aandelen: tellen ze op tot het geheel? ---
  const aandelen = rechthebbenden.map((r) => r.aandeel).filter(Boolean);
  if (aandelen.length && aandelen.length === rechthebbenden.length) {
    const som = _somAandelen(aandelen);
    if (som !== null && Math.abs(som - 1) > 1e-9) {
      zetNiet('niet_rond');
      punten.push({
        id: 'bevoegdheid-aandelen-onvolledig',
        ernst: 'kritiek',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Aandelen van de rechthebbenden tellen niet op tot het geheel',
        constatering: 'Kadastrale aandelen: ' + aandelen.join(' + ') + '.',
        juridisch_kader: 'Alleen de gezamenlijke deelgenoten kunnen over het gehele goed beschikken (art. 3:170 lid 3 BW).',
        actie: 'Stel vast wie het ontbrekende aandeel houdt en betrek die partij bij de akte.',
        bronnen: ['kadaster'],
      });
    } else if (som !== null) {
      onderbouwing.push({ bron: 'kadaster', constatering: 'De aandelen ' + aandelen.join(' + ') + ' vormen samen het geheel.' });
    }
  }

  // --- Titelketen: is de laatste aankomsttitel herkend? ---
  for (const p of (percelen || [])) {
    const verk = Array.isArray(p.verkrijgingen) ? p.verkrijgingen : [];
    if (!verk.length) {
      zetNiet('onbekend');
      punten.push({
        id: 'bevoegdheid-geen-titel',
        ernst: 'aandacht',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Geen aankomsttitel gevonden voor ' + (p.gemeente || '') + ' ' + (p.sectie || '') + ' ' + (p.nummer || ''),
        constatering: 'Voor dit perceel is in de eigendomsinformatie geen "Afkomstig uit stuk" herleid.',
        juridisch_kader: 'Zonder aankomsttitel is niet vast te stellen hoe de rechthebbende het goed heeft verkregen (art. 3:84 BW).',
        actie: 'Raadpleeg de eigendomsinformatie en het brondocument van de laatste verkrijging.',
        bronnen: ['kadaster'],
      });
      break;
    }
  }

  // --- Huwelijk: apart melden, niet bepalend voor de akte-tekst ---
  const huwelijk = _huwelijkTussenComparanten(kl, brpPersonen);
  for (const p of (brpPersonen || [])) {
    const h = p && p.huwelijk;
    if (!h || !h.actueel) continue;
    const partnerIsComparant = kl.some(
      (k) => _achternaamSleutel(k.volledige_naam) === _achternaamSleutel(h.partner_naam)
    );
    if (partnerIsComparant) continue;
    punten.push({
      id: 'bevoegdheid-partner-geen-comparant-' + (_achternaamSleutel(p.volledige_naam) || 'onbekend'),
      ernst: 'aandacht',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Echtgenoot/partner komt niet als comparant voor',
      constatering: `De BRP vermeldt ${p.volledige_naam} als ${(h.soort_verbintenis || 'gehuwd').toLowerCase()} met ${h.partner_naam}; die persoon staat niet in de akte.`,
      juridisch_kader: 'Voor het bezwaren van de echtelijke woning is toestemming van de andere echtgenoot vereist (art. 1:88 lid 1 sub a BW); ontbreekt die, dan is de rechtshandeling vernietigbaar (art. 1:89 BW).',
      actie: 'Vraag de toestemming van de echtgenoot/partner of laat deze meetekenen.',
      bronnen: ['brp'],
    });
  }

  // --- Meer dan één huwelijk of partnerschap op de inzage ---
  // De uitdraai leest alleen de laatste verbintenis volledig uit. Staat er een
  // eerdere bij, dan kan het registergoed uit die eerdere gemeenschap stammen
  // en is met deze stukken niet vast te stellen of daarvoor is verdeeld.
  for (const p of (brpPersonen || [])) {
    const datums = (p && p.verbintenis_datums) || [];
    if (datums.length < 2) continue;
    punten.push({
      id: 'bevoegdheid-meerdere-verbintenissen-' + (_achternaamSleutel(p.volledige_naam) || 'onbekend'),
      ernst: 'aandacht',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Meerdere huwelijken of partnerschappen op de BRP-inzage',
      constatering:
        `De BRP-inzage van ${p.volledige_naam} vermeldt ${datums.length} verbintenissen ` +
        `(${datums.join(', ')}). Alleen de laatste is met partner en eventuele ontbinding uitgelezen.`,
      juridisch_kader: 'Een registergoed dat in een eerdere gemeenschap viel, blijft na ontbinding onverdeeld tot het is verdeeld (art. 1:100 jo. art. 3:170 lid 3 BW).',
      actie: 'Lees de inzage handmatig na op de eerdere verbintenis en stel vast of het registergoed daaruit stamt en of daarvoor een verdeling is ingeschreven.',
      bronnen: ['brp'],
    });
  }

  // --- Weduwe/weduwnaar: geen ex-partner, wel een nalatenschap ---
  for (const p of (brpPersonen || [])) {
    const h = p && p.huwelijk;
    if (!h || !h.ontbonden_door_overlijden) continue;
    punten.push({
      id: 'bevoegdheid-langstlevende-' + (_achternaamSleutel(p.volledige_naam) || 'onbekend'),
      ernst: 'info',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Comparant is weduwe/weduwnaar',
      constatering: `De BRP vermeldt dat het huwelijk van ${p.volledige_naam} met ${h.partner_naam} op ${h.datum_ontbinding} is ontbonden door overlijden.`,
      juridisch_kader: 'Ontbinding door overlijden is geen echtscheiding: er is geen ex-partner, maar wel een nalatenschap (art. 4:182 BW).',
      actie: 'Ga na of de nalatenschap ten aanzien van dit registergoed volledig is afgewikkeld.',
      bronnen: ['brp'],
    });
  }

  // --- Ontbonden huwelijk anders dan door overlijden: echtscheiding ---
  // Alleen de BRP toont dit. Het kadaster noteert de burgerlijke staat
  // uitsluitend ten tijde van verkrijging, en die kan tientallen jaren oud
  // zijn; een scheiding daarna is er niet aan te zien. Zolang de ontbonden
  // gemeenschap niet is verdeeld, kan de ex-partner nog deelgenoot zijn.
  for (const p of (brpPersonen || [])) {
    const h = p && p.huwelijk;
    if (!h || h.actueel || h.ontbonden_door_overlijden) continue;
    const soort = String(h.soort_verbintenis || 'huwelijk').toLowerCase();
    const sleutel = _achternaamSleutel(p.volledige_naam) || 'onbekend';
    const ontbonden = _datumSleutel(h.datum_ontbinding);
    // De ex herkennen we streng (achternaam en voornaam), niet op achternaam
    // alleen: een ex die de naam van de comparant draagt zou anders met de
    // comparant zelf samenvallen en een schoon dossier blokkeren.
    const ex = rechthebbenden.find((r) => _zelfdePersoon(r.volledige_naam, h.partner_naam));
    const zelf = rechthebbenden.some(
      (r) => _achternaamSleutel(r.volledige_naam) === sleutel
    );

    // Titelketen over alle percelen: is er ná de ontbinding verdeeld, en van
    // wanneer dateert de jongste verkrijging?
    let verdeling = null;
    let jongste = null;
    for (const perceel of (percelen || [])) {
      for (const v of (perceel.verkrijgingen || [])) {
        const dv = _datumSleutel(v.ingeschreven_op);
        if (!dv) continue;
        if (!jongste || dv > _datumSleutel(jongste.ingeschreven_op)) jongste = v;
        if (!ontbonden || dv < ontbonden) continue;
        if (!/verdeling|toedeling/.test(String(v.titel_aard || ''))) continue;
        if (!verdeling || dv < _datumSleutel(verdeling.ingeschreven_op)) verdeling = v;
      }
    }
    const jongsteDatum = jongste ? _datumSleutel(jongste.ingeschreven_op) : 0;
    const stuk = (v) => `Hyp${v.register} ${v.deel}/${v.nummer}`;
    const ontbindingszin =
      `De BRP vermeldt dat het ${soort} van ${p.volledige_naam} met ${h.partner_naam} op ` +
      `${h.datum_ontbinding || 'een niet vermelde datum'} is ontbonden` +
      (h.reden_ontbinding ? ` ("${h.reden_ontbinding}")` : '') + '.';

    if (ex) {
      zetNiet('niet_rond');
      punten.push({
        id: 'bevoegdheid-ex-partner-rechthebbende-' + sleutel,
        ernst: 'kritiek',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Ex-partner staat nog als rechthebbende in het kadaster',
        constatering: `${ontbindingszin} Het kadaster vermeldt ${ex.volledige_naam} nog als rechthebbende.`,
        juridisch_kader: 'De ontbonden gemeenschap blijft bestaan tot zij is verdeeld; over het gehele goed kan alleen door alle deelgenoten samen worden beschikt (art. 1:100 jo. art. 3:170 lid 3 BW).',
        actie: 'Ga na of een akte van verdeling is ingeschreven. Zo niet, laat de ex-partner meetekenen of laat de verdeling vóór het passeren inschrijven.',
        bronnen: ['brp', 'kadaster'],
      });
    } else if (!zelf) {
      punten.push({
        id: 'bevoegdheid-scheiding-buiten-kadaster-' + sleutel,
        ernst: 'info',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Ontbonden huwelijk in de inzagestukken, persoon niet in het kadaster',
        constatering: `${ontbindingszin} Deze persoon komt niet als rechthebbende in de eigendomsinformatie voor.`,
        juridisch_kader: 'Een ontbonden gemeenschap raakt de beschikkingsbevoegdheid alleen voor zover de betrokkene rechthebbende is op het registergoed.',
        actie: 'Ga na waarom deze inzage in het dossier zit. Is de betrokkene comparant, controleer dan of er nog een onverdeeldheid speelt.',
        bronnen: ['brp'],
      });
    } else if (verdeling) {
      onderbouwing.push({
        bron: 'kadaster',
        constatering:
          `${ontbindingszin} Op ${verdeling.ingeschreven_op} is een akte van ${verdeling.titel_aard} ` +
          `ingeschreven (${stuk(verdeling)}).`,
      });
    } else if (ontbonden && jongsteDatum && jongsteDatum < ontbonden) {
      punten.push({
        id: 'bevoegdheid-scheiding-zonder-verdeling-' + sleutel,
        ernst: 'aandacht',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Verkregen vóór de ontbinding, geen verdeling ingeschreven',
        constatering:
          `${ontbindingszin} De jongste verkrijging dateert van ${jongste.ingeschreven_op} ` +
          `(${stuk(jongste)}); daarna is geen akte van verdeling of toedeling ingeschreven.`,
        juridisch_kader: 'Een staande huwelijk verkregen registergoed valt in beginsel in de gemeenschap; zonder verdeling blijft de ex-partner deelgenoot (art. 1:100 jo. art. 3:170 lid 3 BW).',
        actie: 'Stel vast of het registergoed in de gemeenschap viel en of de verdeling ten aanzien van dit perceel heeft plaatsgevonden; vraag zo nodig de echtscheidingsbeschikking en het convenant op.',
        bronnen: ['brp', 'kadaster'],
      });
    } else if (ontbonden && jongsteDatum) {
      onderbouwing.push({
        bron: 'kadaster',
        constatering:
          `${ontbindingszin} De jongste verkrijging (${jongste.ingeschreven_op}, ${stuk(jongste)}) ` +
          'dateert van ná die ontbinding.',
      });
    } else {
      punten.push({
        id: 'bevoegdheid-scheiding-datum-onbekend-' + sleutel,
        ernst: 'aandacht',
        categorie: 'Beschikkingsbevoegdheid',
        titel: 'Ontbonden huwelijk, verhouding tot de verkrijging niet vast te stellen',
        constatering:
          `${ontbindingszin} De ontbindingsdatum of de inschrijfdatum van de verkrijging ontbreekt, ` +
          'zodat niet is vast te stellen of het registergoed vóór of ná de ontbinding is verkregen.',
        juridisch_kader: 'Of de ex-partner deelgenoot is, hangt af van het moment van verkrijging ten opzichte van de ontbinding (art. 1:100 BW).',
        actie: 'Stel de ontbindingsdatum en de aankomsttitel handmatig vast en beoordeel of een verdeling nodig is.',
        bronnen: ['brp', 'kadaster'],
      });
    }
  }

  // --- Comparant zonder eigendom: normaal, alleen ter informatie ---
  for (const c of enkelComparant) {
    punten.push({
      id: 'bevoegdheid-comparant-zonder-eigendom',
      ernst: 'info',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Comparant is geen rechthebbende',
      constatering: `${c.volledige_naam} tekent mee als schuldenaar maar staat niet als rechthebbende in het kadaster.`,
      juridisch_kader: 'Een medeschuldenaar die geen rechthebbende is, verbindt zich wel persoonlijk maar vestigt geen hypotheek; de akte kent dan een (derde) hypotheekgever.',
      actie: 'Geen actie nodig indien dit strookt met de passeeropdracht.',
      bronnen: ['kadaster', 'passeeropdracht'],
    });
  }

  // --- Burgerlijke staat wisselt tussen de verkrijgingen ---
  // Het kadaster noteert de staat per verkrijging. Staat dezelfde persoon bij
  // het ene perceel als ongehuwd en bij het andere als gehuwd, dan is er
  // tussen die verkrijgingen een huwelijk gesloten of ontbonden, en kunnen de
  // percelen een verschillend regime kennen.
  for (const r of rechthebbenden) {
    const kernen = [];
    for (const variant of (r.burgerlijke_staat_varianten || [])) {
      const kern = _staatKern(variant);
      if (kern && !kernen.includes(kern)) kernen.push(kern);
    }
    if (kernen.length < 2) continue;
    punten.push({
      id: 'bevoegdheid-staat-wisselt-' + (_achternaamSleutel(r.volledige_naam) || 'onbekend'),
      ernst: 'aandacht',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Burgerlijke staat verschilt per verkrijging',
      constatering:
        `Het kadaster vermeldt ${r.volledige_naam} bij de ene verkrijging als ` +
        `${kernen.join(' en bij de andere als ')} — telkens ten tijde van verkrijging.`,
      juridisch_kader: 'De kadastrale burgerlijke staat geldt per verkrijging. Een verschil betekent dat er tussen de verkrijgingen een huwelijk of partnerschap is gesloten of ontbonden, wat per perceel tot een ander regime kan leiden (art. 1:94 BW).',
      actie: 'Stel per perceel vast of het in een gemeenschap valt en of medewerking van de (ex-)partner nodig is; raadpleeg de BRP voor de actuele staat.',
      bronnen: ['kadaster'],
    });
  }

  // --- Burgerlijke staat alleen bekend ten tijde van verkrijging ---
  const stale = rechthebbenden.filter((r) => r.burgerlijke_staat_peildatum && !_brpKentStaat(r, brpPersonen));
  for (const r of stale) {
    punten.push({
      id: 'bevoegdheid-staat-peildatum',
      ernst: 'info',
      categorie: 'Beschikkingsbevoegdheid',
      titel: 'Burgerlijke staat alleen bekend ten tijde van verkrijging',
      constatering: `Het kadaster vermeldt voor ${r.volledige_naam} "${r.burgerlijke_staat} (ten tijde van verkrijging)"; een actuele BRP-uitdraai ontbreekt.`,
      juridisch_kader: 'De kadastrale burgerlijke staat is een momentopname bij de verkrijging en zegt niets over de situatie nu (art. 1:88 BW-toets vergt de actuele staat).',
      actie: 'Raadpleeg de BRP voor de actuele burgerlijke staat.',
      bronnen: ['kadaster'],
    });
  }

  return { status, rechthebbenden, punten, onderbouwing, huwelijk };
}

function _brpKentStaat(klant, brpPersonen) {
  const sleutel = _achternaamSleutel(klant.volledige_naam);
  return (brpPersonen || []).some(
    (p) => _achternaamSleutel(p.volledige_naam) === sleutel && p.huwelijk
  );
}

const _overlijdens = _parseOverlijdenssignalen(_bronnen);
const _bb = _beoordeelBeschikkingsbevoegdheid(
  Array.isArray(data.kadaster.klanten) ? data.kadaster.klanten : [],
  _brpPersonen,
  _overlijdens,
  _percelen
);

placeholders['<<PERCELEN_RAW>>'] = JSON.stringify(_percelen);
placeholders['<<BESCHIKKINGSBEVOEGDHEID_RAW>>'] = JSON.stringify({
  status: _bb.status,
  rechthebbenden: _bb.rechthebbenden.map((r) => ({
    naam: r.volledige_naam, aanhef: r.aanhef, aandeel: r.aandeel || '',
  })),
  redenen: _bb.punten.filter((p) => p.ernst === 'kritiek' || p.ernst === 'aandacht')
    .map((p) => p.titel),
});
placeholders['<<#FLAG:voorbelasting_bezwaard>>'] =
  _voorbelastingBekend && _heeftVoorbelasting ? 'true' : 'false';
placeholders['<<#FLAG:voorbelasting_onbezwaard>>'] =
  _voorbelastingBekend && !_heeftVoorbelasting ? 'true' : 'false';
placeholders['<<#FLAG:voorbelasting_onbekend>>'] = _voorbelastingBekend ? 'false' : 'true';

// Debiteur-clausule in enkelvoud of meervoud, gelijk oplopend met het aantal
// comparanten onder 1. Bij één cliënt las 'de comparant(en) ... zowel samen als
// ieder afzonderlijk' als een blijven staan sjabloonrest.
const _meerdereClienten = placeholders['<<#FLAG:client_2>>'] === 'true';
// De 'nader te omschrijven' belofte in de onderpandregel hoort een eigen
// omschrijving te krijgen; die sectie verschijnt alleen als er een beperkt
// recht gevonden is.
placeholders['<<#FLAG:beperkte_rechten>>'] =
  _percelen.some((p) => (p.beperkte_rechten || []).length) ? 'true' : 'false';
placeholders['<<#FLAG:debiteur_enkelvoud>>'] = _meerdereClienten ? 'false' : 'true';
placeholders['<<#FLAG:debiteur_meervoud>>'] = _meerdereClienten ? 'true' : 'false';

// Kop van de akte: offertenummer (bank) en het eigen dossiernummer.
placeholders['<<OFFERTENUMMER>>'] =
  _parseOffertenummer(bank_markdown) || String(placeholders['<<OFFERTENUMMER>>'] || '');
placeholders['<<DOSSIERNUMMER>>'] =
  _parseDossiernummer(kadaster_markdown) || _parseDossiernummer(bank_markdown);

const ZAAKNUMMER_TAGS = ['<<ECH_ZAAKNUMMER>>', '<<OFFERTENUMMER>>'];
let zaaknummer = '';
for (const tag of ZAAKNUMMER_TAGS) {
  const v = String(placeholders[tag] || '').trim();
  if (v) { zaaknummer = v; break; }
}
if (!zaaknummer) {
  zaaknummer = String(Date.now());
  for (const tag of ZAAKNUMMER_TAGS) {
    if (tag in placeholders && !placeholders[tag]) {
      placeholders[tag] = zaaknummer;
      break;
    }
  }
}

function firstNonEmpty(...vals) {
  for (const v of vals) {
    if (v != null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
}
const klanten = Array.isArray(kadaster?.klanten) ? kadaster.klanten
  : Array.isArray(bank?.klanten) ? bank.klanten : [];
const klantNamen = klanten
  .map((k) => firstNonEmpty(k?.naam_hoofdletters, k?.volledige_naam, k?.initialen_naam))
  .filter(Boolean);
const klantSamenvatting = klantNamen.length
  ? klantNamen.slice(0, 3).join(' / ')
  : '';

const templatePath = `/data/shared/templates/${bankId}/${bankConfig.template_filename}`;

return {
  json: {
    bankId,
    bankDisplayName: bankConfig.display_name || bankId,
    zaaknummer,
    templatePath,
    placeholders,
    klantSamenvatting,
    beschikkingsbevoegdheid: {
      status: _bb.status,
      aandachtspunten: _bb.punten,
      onderbouwing: _bb.onderbouwing,
      rechthebbenden: _bb.rechthebbenden.map((r) => ({
        naam: r.volledige_naam,
        aandeel: r.aandeel || '',
        burgerlijke_staat: r.burgerlijke_staat || '',
        burgerlijke_staat_peildatum: !!r.burgerlijke_staat_peildatum,
      })),
    },
    analysisInput: {
      bank_markdown,
      kadaster_markdown: (() => {
        // dossier_markdown komt nu mee in de Aggregate-input (vroeger
        // via $getWorkflowStaticData('global').dossierExtraMarkdownByExec).
        const extra = String(
          (bankDoc && bankDoc.dossier_markdown) ||
          (kadDoc && kadDoc.dossier_markdown) || ''
        ).trim();
        const core = kadaster_markdown;
        if (!extra) return core;
        return `${core}\n\n=== Overige dossier-PDFs (geen onderdeel van kadaster-extractie) ===\n${extra}`;
      })(),
      extracted: { bank, kadaster }
    },
    debug: {
      bank,
      kadaster
    }
  }
};

// Deterministische juridische checks op de geëxtraheerde data van
// passeeropdracht (bank) en kadaster. Levert aandachtspunten in dezelfde
// shape op als de LLM-analyse zodat de Parse-stap ze samen kan voegen.
//
// Wat deze node WEL doet (100% betrouwbaar, geen LLM):
//   1. Klantentelling: aantal schuldenaren ↔ aantal rechthebbenden
//   2. Achternaam-mismatch per klant (op volgorde gepaard)
//   3. Onderpand-gemeente vs. kadastrale gemeente
//
// Wat deze node NIET doet: bedragen-arithmetiek (die volgt 1-op-1 uit de
// passeeropdracht en heeft geen juridische waarde — eventueel als
// extractie-QA in een aparte stap).
//
// Output:
//   { ...alle velden van Build Placeholders..., deterministic_aandachtspunten: [...] }

const src = $json || {};
const extracted = (src.analysisInput && src.analysisInput.extracted) || (src.debug || {}) || {};
const bank = extracted.bank || {};
const kadaster = extracted.kadaster || {};
const bankKlanten = Array.isArray(bank.klanten) ? bank.klanten : [];
const kadKlanten = Array.isArray(kadaster.klanten) ? kadaster.klanten : [];

function stripAccents(s) {
  return String(s || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '');
}
function normName(s) {
  return stripAccents(s).toLowerCase().replace(/[^a-z]/g, '');
}
function normWord(s) {
  return stripAccents(s).toLowerCase().replace(/[^a-z0-9]/g, '');
}
function lastSurnameToken(s) {
  const cleaned = String(s || '')
    .replace(/[,.;]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!cleaned) return '';
  // Pak het laatste woord — bij dubbele achternamen ('Schmidt-de Klerk')
  // levert dat 'Klerk' op, wat als anker voor mismatch volstaat.
  const parts = cleaned.split(' ').filter(Boolean);
  return normName(parts[parts.length - 1] || '');
}
function bestName(klant) {
  return (
    klant?.naam_hoofdletters ||
    klant?.volledige_naam ||
    klant?.naam ||
    klant?.initialen_naam ||
    ''
  );
}

const aandachtspunten = [];

// --- 1. Klantentelling --------------------------------------------------
if (bankKlanten.length > 0 && kadKlanten.length > 0 && bankKlanten.length !== kadKlanten.length) {
  aandachtspunten.push({
    id: 'klantentelling-mismatch',
    ernst: 'kritiek',
    categorie: 'Identiteit',
    titel: 'Aantal schuldenaren wijkt af van aantal rechthebbenden',
    constatering: `Passeeropdracht noemt ${bankKlanten.length} schuldena(a)r(en); Kadaster vermeldt ${kadKlanten.length} rechthebbende(n).`,
    juridisch_kader: 'Schuldenaren in de hypotheekakte moeten in beginsel gelijk zijn aan de rechthebbenden op het onderpand. Afwijking duidt op (gelijktijdige) overdracht, vererving of een ontbrekende partij.',
    actie: 'Verifieer of een eigendomsoverdracht (koopakte) gelijktijdig passeert, of dat een rechthebbende ontbreekt in een van de stukken.',
    bronnen: ['passeeropdracht', 'kadaster']
  });
}

// --- 2. Achternaam-mismatch per klantpositie ---------------------------
const pairs = Math.min(bankKlanten.length, kadKlanten.length);
for (let i = 0; i < pairs; i++) {
  const bRaw = bestName(bankKlanten[i]);
  const kRaw = bestName(kadKlanten[i]);
  const bLast = lastSurnameToken(bRaw);
  const kLast = lastSurnameToken(kRaw);
  if (!bLast || !kLast) continue;
  if (bLast === kLast) continue;
  // Soft-match: 'klerk' in 'schmidtdeklerk' of andersom (dubbele achternaam)
  if (bLast.includes(kLast) || kLast.includes(bLast)) continue;
  aandachtspunten.push({
    id: `naam-mismatch-klant-${i + 1}`,
    ernst: 'kritiek',
    categorie: 'Identiteit',
    titel: `Achternaam klant ${i + 1} verschilt tussen bank en kadaster`,
    constatering: `Passeeropdracht: "${bRaw}". Kadaster: "${kRaw}". Achternamen komen niet overeen.`,
    juridisch_kader: 'De rechthebbende op het onderpand moet de hypotheek vestigen. Naamverschil kan duiden op recente naamswijziging (huwelijk/echtscheiding), vererving, of een geplande eigendomsoverdracht.',
    actie: 'Vergelijk met BRP/legitimatie. Vraag indien nodig verklaring van erfrecht, koopakte of huwelijksakte op.',
    bronnen: ['passeeropdracht', 'kadaster']
  });
}

// --- 3. Onderpand-gemeente vs. kadastrale gemeente --------------------
const bankWoon = normWord(bank.onderpand_woonplaats);
const kadGem = normWord(kadaster.kadastrale_gemeente);
if (bankWoon && kadGem && bankWoon !== kadGem && !bankWoon.includes(kadGem) && !kadGem.includes(bankWoon)) {
  aandachtspunten.push({
    id: 'onderpand-gemeente-mismatch',
    ernst: 'aandacht',
    categorie: 'Onderpand',
    titel: 'Onderpand-woonplaats wijkt af van kadastrale gemeente',
    constatering: `Passeeropdracht onderpand-woonplaats: "${bank.onderpand_woonplaats || ''}". Kadastrale gemeente: "${kadaster.kadastrale_gemeente || ''}".`,
    juridisch_kader: 'Het in de akte op te nemen onderpand moet ondubbelzinnig overeenkomen met het kadastrale perceel. Een verschil tussen woonplaats en kadastrale gemeente kan duiden op gemeentelijke herindeling — of op een verkeerd perceel.',
    actie: 'Verifieer of woonplaats en kadastrale gemeente werkelijk hetzelfde perceel betreffen (gemeentelijke herindeling toegestaan; verkeerd perceel niet).',
    bronnen: ['passeeropdracht', 'kadaster']
  });
}

// --- 4. Beschikkingsbevoegdheid ------------------------------------------
// Build Placeholders heeft dit al deterministisch beoordeeld op kadaster, BRP
// en aankomsttitels. Hier voegen we die punten alleen samen met de overige
// checks, zodat de webapp één lijst krijgt.
const bevoegdheid = src.beschikkingsbevoegdheid || {};
for (const punt of (Array.isArray(bevoegdheid.aandachtspunten) ? bevoegdheid.aandachtspunten : [])) {
  aandachtspunten.push(punt);
}

// Kritiek eerst, dan aandacht, dan info: de behandelaar moet bovenaan zien wat
// het passeren blokkeert.
const ERNST_VOLGORDE = { kritiek: 0, aandacht: 1, info: 2 };
aandachtspunten.sort(
  (a, b) => (ERNST_VOLGORDE[a.ernst] ?? 3) - (ERNST_VOLGORDE[b.ernst] ?? 3)
);

// Passthrough alle Build-Placeholders-velden + deterministic_aandachtspunten
return {
  json: {
    ...src,
    deterministic_aandachtspunten: aandachtspunten
  }
};

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

werkJobBij({ status: 'akte opmaken', fase: 3 });

// Schrijft de Python-argumenten naar een tijdelijk JSON-bestand zodat
// executeCommand geen payload-data hoeft te interpoleren via single-quotes.
// Voorkomt shell-injection bij apostrofs of quotes in zaaknummer/klant/etc.
// vul_template_in.py verwijdert het bestand na inlezen (best-effort cleanup).
const execId = String($execution.id || 'single').replace(/[^0-9A-Za-z_-]/g, '_').slice(0, 32);
const argsFile = `/tmp/n8n_args_akte_${execId}_${Date.now()}.json`;
const j = $json || {};
const payload = {
  template: j.templatePath,
  placeholders: j.placeholders,
  zaaknummer: String(j.zaaknummer || ''),
};
fs.writeFileSync(argsFile, JSON.stringify(payload), 'utf8');
return { json: { ...j, argsFile } };

const fs = require('fs');
const JOB_PAD = `/data/shared/jobs/${$('Create Job').first().json.jobId}.json`;

function werkJobBij(velden) {
  let job = {};
  try {
    job = JSON.parse(fs.readFileSync(JOB_PAD, 'utf8'));
  } catch (_) {
    // Jobbestand weg (opgeruimd?): dan schrijven we het opnieuw aan.
  }
  const nieuw = { ...job, ...velden, bijgewerkt_op: new Date().toISOString() };
  fs.writeFileSync(JOB_PAD, JSON.stringify(nieuw), 'utf8');
  return nieuw;
}

// Schrijft het eindresultaat in het jobbestand; de webapp haalt het bij de
// volgende poll op. De HTTP-respons (het job_id) is al bij binnenkomst
// verstuurd, dus hier gaat niets meer over de lijn.
//
// De payload-vorm is ongewijzigd gebleven ten opzichte van de synchrone versie,
// zodat de webapp dezelfde velden blijft lezen.
const akteNode = $('Generate DOCX').first()?.json || {};
const akteStdout = String(akteNode.stdout || '');
const akteStderr = String(akteNode.stderr || '');
const akteMatch = akteStdout.match(/SUCCESS:\s*(.+)/);
const aktePath = akteMatch ? akteMatch[1].trim() : '';

// Geen document: eerst de job op 'fout' zetten, pas daarna gooien. Andersom
// blijft de job op 'akte opmaken' hangen en wacht de webapp op een antwoord dat
// nooit komt.
if (!aktePath) {
  const melding = `Geen SUCCESS-pad in de akte-output. stdout=${akteStdout.slice(0, 200)}; stderr=${akteStderr.slice(0, 200)}`;
  werkJobBij({ status: 'fout', fase: 4, fout: melding });
  throw new Error(melding);
}

const akteFilename = aktePath.split('/').pop();

// REPLACED_BLOCKS = 0 betekent dat het Python-script geen enkele
// placeholder kon vervangen. Meestal duidt dat op een template/registry
// mismatch (placeholder-naam fout gespeld, of verkeerd bank-template).
// We falen niet — de .docx bestaat — maar geven de notaris een
// duidelijke waarschuwing.
const replacedMatch = akteStdout.match(/REPLACED_BLOCKS:\s*(\d+)/);
const replacedBlocks = replacedMatch ? parseInt(replacedMatch[1], 10) : null;

const placeholdersNode = $('Build Placeholders').first()?.json || {};
const template_warning = replacedBlocks === 0
  ? `Python script meldde REPLACED_BLOCKS=0: geen placeholders vervangen in template '${placeholdersNode.bankId || '?'}'. Controleer of de template en de registry-placeholder-tags overeenkomen.`
  : null;

const resultaat = {
  success: true,
  mode: 'akte',
  template_warning,
  replaced_blocks: replacedBlocks,
  filename: akteFilename,
  file_path: aktePath,
  download_url: `http://localhost:8080/output/${akteFilename}`,
  preview_url: `http://localhost:8080/output/${akteFilename.replace(/\.docx$/i, '.html')}`,
  bank_id: placeholdersNode.bankId || null,
  bank_display_name: placeholdersNode.bankDisplayName || null,
  klant_samenvatting: placeholdersNode.klantSamenvatting || '',
  zaaknummer: placeholdersNode.zaaknummer || '',
  analysis: null,
  // Deterministisch oordeel over de beschikkingsbevoegdheid (kadaster, BRP en
  // aankomsttitels). Vorm is gelijk aan die van de juridische analyse, zodat de
  // webapp dezelfde component kan gebruiken.
  beschikkingsbevoegdheid: (() => {
    const checks = $('Deterministic Checks').first()?.json || {};
    const bevoegdheid = checks.beschikkingsbevoegdheid || placeholdersNode.beschikkingsbevoegdheid || null;
    if (!bevoegdheid) return null;
    // Alleen de punten die over bevoegdheid gaan. De overige deterministische
    // checks (naam-mismatch, klantentelling, gemeente) horen bij een andere
    // categorie en zouden de telling van dit paneel vertekenen.
    const punten = (Array.isArray(bevoegdheid.aandachtspunten) ? bevoegdheid.aandachtspunten : [])
      .filter((p) => p && p.categorie === 'Beschikkingsbevoegdheid');
    const tel = (e) => punten.filter((p) => p && p.ernst === e).length;
    const SAMENVATTING = {
      rond: 'De beschikkingsbevoegdheid sluit: de rechthebbende(n) uit het kadaster zijn comparant en de aankomsttitel is herleid.',
      onbekend: 'De beschikkingsbevoegdheid kon niet volledig worden vastgesteld; de akte bevat op dit punt een invulmarker.',
      niet_rond: 'De beschikkingsbevoegdheid sluit NIET. De akte bevat op dit punt een invulmarker in plaats van een verklaring.',
    };
    return {
      status: bevoegdheid.status || 'onbekend',
      samenvatting: SAMENVATTING[bevoegdheid.status] || SAMENVATTING.onbekend,
      aandachtspunten: punten,
      onderbouwing: bevoegdheid.onderbouwing || [],
      rechthebbenden: bevoegdheid.rechthebbenden || [],
      counts: { kritiek: tel('kritiek'), aandacht: tel('aandacht'), info: tel('info') },
    };
  })(),
};

const job = werkJobBij({
  status: 'klaar',
  fase: 4,
  fout: null,
  resultaat,
});

return [{ json: job }];

// Maakt het jobbestand aan waar de rest van de workflow zijn voortgang in
// bijhoudt, en laat de binaries ongemoeid doorlopen naar Split Input Files.
const item = $input.first();

const fs = require('fs');
const JOB_DIR = '/data/shared/jobs';
const nu = new Date();
const stempel =
  nu.getFullYear() +
  String(nu.getMonth() + 1).padStart(2, '0') +
  String(nu.getDate()).padStart(2, '0') +
  '_' +
  String(nu.getHours()).padStart(2, '0') +
  String(nu.getMinutes()).padStart(2, '0') +
  String(nu.getSeconds()).padStart(2, '0');
const jobId = `akte_${stempel}_${String($execution.id || Math.random().toString(36).slice(2))}`
  .replace(/[^0-9A-Za-z_-]/g, '_');

fs.mkdirSync(JOB_DIR, { recursive: true });

// Oude jobbestanden opruimen; ze bevatten dossierinhoud en horen niet langer te
// blijven staan dan nodig is om het resultaat op te halen.
const BEWAARTERMIJN_MS = 24 * 60 * 60 * 1000;
try {
  for (const naam of fs.readdirSync(JOB_DIR)) {
    if (!naam.endsWith('.json')) continue;
    const pad = `${JOB_DIR}/${naam}`;
    if (Date.now() - fs.statSync(pad).mtimeMs > BEWAARTERMIJN_MS) fs.unlinkSync(pad);
  }
} catch (_) {
  // Best-effort: een nieuwe akte mag hier niet op stuklopen.
}

const documentCount = Object.keys(item.binary || {}).length;

fs.writeFileSync(
  `${JOB_DIR}/${jobId}.json`,
  JSON.stringify({
    job_id: jobId,
    soort: 'akte',
    status: 'documenten omzetten',
    fase: 1,
    document_count: documentCount,
    resultaat: null,
    fout: null,
    gestart_op: nu.toISOString(),
    bijgewerkt_op: nu.toISOString(),
  }),
  'utf8'
);

return [{ json: { ...(item.json || {}), jobId, documentCount }, binary: item.binary }];
